test('RISK corrupt cloud work budget: completed pending-source refusals do not restart downloads on ordinary edits',{timeout:30000},async t=>{
 for(const control of ['unrepresented pending with typed authority','JSON-lossy pending','BigInt pending','cyclic pending'])await t.test(control,async sub=>{
  const app=await damagedAcknowledgedApp187(sub),{ctx,shim,backend,originalRoot,originalHeader}=app,store=ctx.window.ScannerDeviceStore;
  if(control==='unrepresented pending with typed authority'){
   app.faults.transactionRead=async(path,docs)=>{if(path.startsWith('users/owner/generations/')&&!path.includes('/chunks/')&&docs.get(path)?.state==='staging'&&[...docs.keys()].some(key=>key.startsWith(path+'/chunks/')))throw Object.assign(Error('isolated original pending upload'),{code:'unavailable'});};
   assert.equal((await backend.CS.push(JSON.stringify({v:2,tasks:[{id:'pending-only-budget',title:'Pending-only work',ctx:[]}],futurePending:{keep:'exact original'}}),1792322999999,originalRoot.rev)).error,true);delete app.faults.transactionRead;
   const pending=await store.getPendingUpload('owner');await editRawDevice187(app.indexedDB,app.deviceDbName,tx=>tx.objectStore('meta').put({...pending,futurePending:9n},'pending:owner'));
  }else{
   let future;if(control==='JSON-lossy pending'){future=new Array(1);future.future='sole pending field outside JSON';}else if(control==='BigInt pending')future=9n;else{future={keep:'cyclic original'};future.self=future;}
   backend.docs.set('users/owner/generations/budget-lossy-pending',{...originalHeader,state:'staging',baseRev:originalRoot.rev});for(const chunk of app.activeSource.chunks)backend.docs.set('users/owner/generations/budget-lossy-pending/chunks/'+chunk.index,structuredClone(chunk));
   await editRawDevice187(app.indexedDB,app.deviceDbName,tx=>tx.objectStore('meta').put({generationId:'budget-lossy-pending',payloadHash:originalHeader.hash,baseRev:originalRoot.rev,updatedAt:1,account:'owner',futurePending:future},'pending:owner'));
  }
  const pending=await store.getPendingUpload('owner');const originalCloud=JSON.stringify([...backend.docs]),writes=backend.writes.length;let reads=0;app.faults.serverRead=async()=>{reads++;};sub.after(()=>{delete app.faults.serverRead;});
  await fixtureDeadline(ctx.cloudPull(),'pending source check settles within its original bounded attempt',7000);assert.equal(backend.docs.get('users/owner').rev,originalRoot.rev);const initialReads=reads,byAction=[];assert.ok(initialReads>0);ctx.window.CLOUD_PUSH_DELAY_MS=0;
  const settle=async()=>{assert.equal(await ctx.persist(),true);await fixtureDeadline(async wait=>{for(;;){await wait(5);if(!vm.runInContext('pulling||cloudPushInFlight||cloudTimer!==null',ctx))break;}},'pending-held ordinary action saves durably');assert.equal((await store.readHead()).payload,JSON.stringify(ctx.state));byAction.push(reads-initialReads);};
  shim.document.getElementById('addInput').value='Accepted while pending recovery needs a choice';await ctx.onAction('add',{});await settle();ctx.onAction('start-scan',{dataset:{mode:'descending'}});await settle();
  const candidate=ctx.state.candidateId,benchmark=ctx.state.chain.at(-1);assert.ok(candidate&&benchmark);ctx.onAction('no',{dataset:{candidate,benchmark}});await settle();assert.equal(ctx.state.considered[candidate],'no');const done=ctx.state.chain.at(-1);ctx.onAction('bench-done',{dataset:{benchmark:done}});await settle();assert.equal(ctx.state.tasks.find(row=>row.id===done).done,true);
  assert.equal(JSON.stringify([...backend.docs]),originalCloud);assert.equal(backend.writes.length,writes);assert.deepEqual(await store.getPendingUpload('owner'),pending,'even JSON-lossy unknown physical fields remain exact');assert.equal(ctx.state.syncDirty,true);
  sub.diagnostic(control+' additional SDK reads: '+JSON.stringify(byAction));assert.equal(reads,initialReads,'a completed pending-source refusal cannot reset the corrupt-source download budget for every edit');
  const readPending=store.getPendingUpload;store.getPendingUpload=async()=>{throw Object.assign(Error('isolated unavailable local pending read'),{name:'AbortError'});};try{await ctx.sendPush();assert.equal(reads,initialReads,'an unavailable local pending read cannot authorize another cloud download');}finally{store.getPendingUpload=readPending;}await ctx.sendPush();assert.equal(reads,initialReads,'a later available local read keeps the unchanged refusal bounded');

  await ctx.onAction('sync-retry',{});assert.ok(reads>initialReads,'explicit Retry remains live for a pending-source hold');assert.equal(JSON.stringify([...backend.docs]),originalCloud);assert.deepEqual(await store.getPendingUpload('owner'),pending);
  // An independent compatible peer may replace the local pointer. Retain the
  // original physical value (including non-JSON data) before simulating it.
  await editRawDevice187(app.indexedDB,app.deviceDbName,tx=>tx.objectStore('meta').put(pending,'fixture-original-pending-budget'));
  const replacement={...pending,updatedAt:pending.updatedAt+1};await editRawDevice187(app.indexedDB,app.deviceDbName,tx=>tx.objectStore('meta').put(replacement,'pending:owner'));const beforePeer=reads;await ctx.sendPush();await settle();assert.ok(reads>beforePeer,'changed local pending evidence releases only to a fresh source check');assert.equal(JSON.stringify([...backend.docs]),originalCloud);assert.deepEqual(await store.getPendingUpload('owner'),replacement);
  if(control!=='unrepresented pending with typed authority'){
   const compatible={...replacement};delete compatible.futurePending;await store.setPendingUpload('owner',compatible);await ctx.sendPush();await fixtureDeadline(async wait=>{while(vm.runInContext('pulling||cloudPushInFlight',ctx))await wait(5);},'a same-pointer losslessness change permits a fresh guarded repair');const final=await settleRecovery188(app);assert.ok(final.remote.rev>originalRoot.rev);assert.equal(ctx.state.tasks.find(row=>row.id===done).done,true);assert.ok(JSON.parse(final.remote.payload).tasks.some(row=>row.title==='Accepted while pending recovery needs a choice'));
  }
  const graph=await store.readRawExportSnapshot(),meta=graph.stores.meta;assert.deepEqual(meta.values[meta.keys.indexOf('fixture-original-pending-budget')],pending,'the compatible-peer fixture retains every exact original non-JSON value');

 });
});

test('RISK corrupt cloud work budget: a failed exact-source read does not permanently hold a later repair',async t=>{
 const app=await damagedAcknowledgedApp187(t),{ctx,shim,backend,originalRoot}=app;let roots=0,failed=false;
 app.faults.serverRead=async path=>{if(path==='users/owner'&&++roots===3){failed=true;throw Object.assign(Error('Synthetic transient exact-source read'),{code:'unavailable'});}};
 refuseNextRecoveryTransaction255(app.faults);await ctx.cloudPull();assert.equal(failed,true,'the ordinary corrupt pull reached its separate exact-copy read');assert.equal(backend.docs.get('users/owner').rev,originalRoot.rev);
 delete app.faults.serverRead;
 shim.document.getElementById('addInput').value='Accepted after a transient exact-source read';await ctx.onAction('add',{});assert.equal(await ctx.persist(),true);await ctx.sendPush();
 await fixtureDeadline(async wait=>{while(vm.runInContext('pulling||cloudPushInFlight',ctx))await wait(5);},'the edit-triggered app operation settles before the external verification read');
 const {remote}=await settleRecovery188(app);
 assert.ok(remote.rev>originalRoot.rev,'a transient failed check cannot be treated as proof that the exact acknowledged copy is unrepairable');
 assert.ok(JSON.parse(remote.payload).tasks.some(row=>row.title==='Accepted after a transient exact-source read'));
});

test('RISK resilient sync recovery: an exact acknowledged copy recovers missing cloud chunks and publishes subsequent local work',async t=>{
 const app=await damagedAcknowledgedApp187(t),{ctx,shim,backend,originalRoot,originalHeader,acknowledgedTasks}=app;
 shim.document.getElementById('addInput').value='Local work after source damage';
 await ctx.onAction('add',{});assert.equal(await ctx.persist(),true);
 const held=await backend.CS.pull();assert.equal(held.code,'corrupt-generation','the external fixture must reach the genuine missing-chunk decoder failure');
 await ctx.cloudPull();await ctx.sendPush();
 const {remote:recovered}=await settleRecovery188(app);
 assert.equal(recovered.error,undefined,'a verified exact acknowledged copy must restore functional sync instead of indefinitely holding every push');
 assert.ok(recovered.rev>originalRoot.rev,'recovery publishes through a new conditional revision');
 assert.notEqual(backend.docs.get('users/owner').activeGeneration,originalRoot.activeGeneration,'the damaged published generation is never refilled or overwritten');
 const board=JSON.parse(recovered.payload);
 for(const task of acknowledgedTasks)assert.deepEqual(board.tasks.find(row=>row.id===task.id),task,'acknowledged tasks retain their complete fields');
 assert.ok(board.tasks.some(row=>row.title==='Local work after source damage'),'the subsequent accepted edit reaches the actual cloud payload');
 assert.deepEqual(backend.docs.get('users/owner/generations/'+originalRoot.activeGeneration),originalHeader,'the damaged source header remains exact');
 await settleRecovery188(app);
 const reopened=await loadApp({sharedStorage:shim.localStorage,indexedDBProvider:app.indexedDB,deviceDbName:app.deviceDbName});
 t.after(()=>closeLegacyApp173(reopened));
 assert.ok(reopened.ctx.state.tasks.some(row=>row.title==='Local work after source damage'),'the recovered ACK and edit survive durable reopen');
 assert.equal(reopened.ctx.state.syncDirty,false,'only the actual acknowledged result is called synced');
 for(const [key,raw] of app.previousSource)assert.equal(JSON.stringify(backend.docs.get(key)),raw,'recovery keeps the formerly previous complete source even after publication');
});

test('RISK resilient sync recovery: a failed rebuild protects every source and retries after another local edit',async t=>{
 const app=await damagedAcknowledgedApp187(t),{ctx,shim,backend,originalRoot}=app;
 app.faults.push=Object.assign(Error('isolated offline rebuild'),{code:'unavailable'});
 await ctx.cloudPull();
 for(let i=0;i<100&&backend.CS.errorStage!=='push';i++)await syncSettle(10);
 assert.equal(backend.CS.errorCode,'unavailable','the genuine SDK-boundary upload fails after recovery evidence was captured');
 assert.equal(backend.docs.get('users/owner').rev,originalRoot.rev);
 const preserved=await ctx.window.ScannerDeviceStore.listOpaqueArchives();
 assert.ok(preserved.some(row=>row.key.startsWith('cloud-generation-recovery:')),'the failed attempt has durable protected evidence');
 shim.document.getElementById('addInput').value='Accepted between recovery attempts';
 await ctx.onAction('add',{});assert.equal(await ctx.persist(),true);
 delete app.faults.push;
 await ctx.cloudPull();await ctx.sendPush();
 const {remote}=await settleRecovery188(app);
 assert.ok(JSON.parse(remote.payload).tasks.some(row=>row.title==='Accepted between recovery attempts'),'a later edit cannot invalidate all future safe recovery');
 const retained=await ctx.window.ScannerDeviceStore.listOpaqueArchives();
 for(const row of preserved)assert.ok(retained.some(copy=>copy.key===row.key&&copy.raw===row.raw),'a later attempt never replaces the earlier exact evidence');
});

