test('RISK task rating history browser: phone tablet and desktop disclosures pagination drafts and offline Undo preserve actual observations',{skip:!process.env.LANDSCAPE_BROWSER_URL},async()=>{
 const {chromium,webkit}=await import(process.env.LANDSCAPE_PLAYWRIGHT);
 const facts=rows=>rows.slice().sort((a,b)=>a.id.localeCompare(b.id));
 for(const [name,type,options] of [['chrome',chromium,{channel:'chrome'}],['webkit',webkit,{}]]){
  const browser=await type.launch(options);
  try{for(const [width,height] of [[320,568],[568,320],[768,1024],[1440,900]])for(const colorScheme of ['light','dark']){
   const context=await browser.newContext({viewport:{width,height},hasTouch:width<1000,isMobile:width<1000,colorScheme,reducedMotion:'reduce'}),page=await context.newPage();
   try{
    await page.route('https://**/*',route=>route.abort());await page.goto(process.env.LANDSCAPE_BROWSER_URL);await page.waitForFunction(()=>typeof state!=='undefined'&&state!==null);
    // Complete the real browser-local welcome choice so cold reload retains it.
    await page.locator('#motionDialog button[data-landscape-motion="reduced"]').click();
    await page.waitForFunction(()=>LivingSky.readMotion(localStorage)==='reduced'&&!document.getElementById('motionDialog').open);
    const fixture=await page.evaluate(()=>{closeModal();state.seenQuickStart=true;const a=addTask('Private browser benchmark'),b=addTask('Private browser rating history');state.chain=[a.id];state.candidateId=b.id;recomputeRanks();decide('yes');const row=JSON.parse(JSON.stringify(b.ratingHistory[0]));b.ratingHistory=Array.from({length:45},(_,i)=>({...row,id:'private-browser-event-'+i,seq:45-i,at:row.at-i*1000}));b.ratingHistoryHead=b.ratingHistory[0].id;state.listOpen=true;render();return {id:b.id,raw:JSON.stringify(b.ratingHistory)};});
    const row=page.locator('[data-row]').filter({has:page.locator('[data-act="edit"][data-id="'+fixture.id+'"]')});await row.locator('[data-act="edit"]').click();
    const summary=page.locator('.task-rating-history > summary');await summary.focus();await summary.press('Enter');await page.locator('.rating-event').first().waitFor();assert.equal(await page.locator('.rating-event').count(),20);
    await page.locator('#etTitle').fill('Unsaved private history draft');await page.getByRole('button',{name:/Show 20 more/}).click();assert.equal(await page.locator('.rating-event').count(),40);assert.equal(await page.locator('#etTitle').inputValue(),'Unsaved private history draft');
    await page.getByRole('button',{name:/Show 20 more/}).click();assert.equal(await page.locator('.rating-event').count(),45);assert.equal(await summary.evaluate(e=>document.activeElement===e),true,'the last pagination click must retain keyboard focus on the disclosure');
    assert.equal(await page.evaluate(id=>JSON.stringify(taskById(id).ratingHistory),fixture.id),fixture.raw,'opening and paging do not edit facts');
    const layout=await page.locator('.modal').evaluate(el=>({width:el.clientWidth,scroll:el.scrollWidth,children:[...el.querySelectorAll('.rating-values dt,.rating-values dd,.rating-event time')].map(x=>{const a=x.getBoundingClientRect(),p=el.getBoundingClientRect();return {left:a.left-p.left,right:a.right-p.left};})}));assert.ok(layout.scroll<=layout.width+1,'history must fit the pane');assert.ok(layout.children.every(box=>box.left>=0&&box.right<=layout.width+3),'timestamps and values stay inside the phone/tablet pane');
    if(process.env.RATING_HISTORY_SCREENSHOTS){const fs=await import('node:fs/promises');await fs.mkdir(process.env.RATING_HISTORY_SCREENSHOTS,{recursive:true});await page.screenshot({path:path.join(process.env.RATING_HISTORY_SCREENSHOTS,`${name}-${width}x${height}-${colorScheme}.png`)});}
    if(width===320&&colorScheme==='light'){
     const offline=name==='chrome';
     await page.locator('#etTitle').fill('Private browser rating history');await page.locator('[data-act="save-edit"]').click();await page.evaluate(()=>persist());
     await page.waitForFunction(()=>!!navigator.serviceWorker.controller);if(offline)await context.setOffline(true);await page.reload();await page.waitForFunction(id=>typeof state!=='undefined'&&state?.tasks.some(t=>t.id===id),fixture.id);
     assert.deepEqual(facts(await page.evaluate(id=>taskById(id).ratingHistory,fixture.id)),facts(JSON.parse(fixture.raw)),(offline?'offline':'online')+' cold reload retains every exact original fact and does not record resampled rank noise');
     await page.evaluate(id=>doneTask(id),fixture.id);await page.locator('[data-act="undo"]').click();await page.evaluate(()=>persist());assert.equal(await page.evaluate(id=>taskById(id).done,fixture.id),false);
     const reversed=await page.evaluate(id=>taskById(id).ratingHistory,fixture.id);assert.ok(reversed.some(r=>r.kind==='undo'));if(offline)await context.setOffline(false);await page.reload();await page.waitForFunction(id=>typeof state!=='undefined'&&state?.tasks.some(t=>t.id===id),fixture.id);assert.deepEqual(facts(await page.evaluate(id=>taskById(id).ratingHistory,fixture.id)),facts(reversed),(offline?'reconnect':'online')+' reload keeps every exact completion and Undo fact');
    }
   }finally{await context.close();}
  }}finally{await browser.close();}
 }
});

test('RISK shared scenery: the same seed and UTC instant select identical events after different open frame and interruption histories',()=>{
 const a=sceneTimeline(),b=sceneTimeline(),seed='private-scene-fixture',clock=Date.parse('2026-10-06T03:23:42.125Z');
 const options={seed,season:'summer',sunAt:()=>({altitude:-20,azimuth:0})};
 const first=a.LandscapeTimeline.create(options),late=b.LandscapeTimeline.create(options);
 const snapshot=value=>JSON.parse(JSON.stringify(value));
 const expected=snapshot(late.at(clock));
 for(const hz of [24,30,60,120]){
  for(let i=0;i<100;i++){Math.random();first.at(clock-10000+i*1000/hz);}
  assert.deepEqual(snapshot(first.at(clock)),expected,`${hz} Hz and UI draws cannot change the scene`);
 }
 assert.deepEqual(snapshot(first.at(clock+86400000)),snapshot(late.at(clock+86400000)),'reload and an offline day of suspended history do not queue events');
 assert.deepEqual(snapshot(first.at(clock-86400000)),snapshot(late.at(clock-86400000)),'a clock correction reconstructs the selected instant');
 assert.notDeepEqual(snapshot(a.LandscapeTimeline.create({...options,seed:'other-private-seed'}).at(clock)),expected,'an explicit initial seed still controls the scene');
 assert.deepEqual(snapshot(a.LandscapeTimeline.create({...options,seed:undefined}).at(clock)),snapshot(a.LandscapeTimeline.create({...options,seed:null}).at(clock)),'old/missing seeds use the immutable shared fallback without creating one in task storage');
 for(const at of [clock-8,clock+8])for(const event of expected.events){
  const retained=first.at(at).events.find(candidate=>candidate.id===event.id);
  if(retained)assert.ok(Math.abs((retained.age-event.age)-(at-clock)/1000)<1e-7,'retained visitors move by UTC age, not frame accumulation');
 }
});

test('RISK shared scenery: deterministic opportunities preserve rail rare-show refractory periods and finite complete lifetimes',()=>{
 const context=sceneTimeline(),timeline=context.LandscapeTimeline.create({seed:'private-schedule',season:'summer',sunAt:()=>({altitude:-20,azimuth:0})});
 const start=Date.parse('2026-10-05T23:40Z'),seen=new Map();
 for(let second=0;second<=7200;second+=3){
  const scene=timeline.at(start+second*1000);
  assertPedestrianReservationBound(scene);assert.ok(scene.woodland.length<=4);
  for(const type of ['train','metro','banner','skywriter','meteor','bird','dolphin'])assert.ok(scene.events.filter(e=>e.type===type).length<=1,`${type} does not overlap itself`);
  assert.ok(scene.events.filter(e=>['festival','fireworks'].includes(e.type)).length<=1,'barge and standalone fireworks do not overlap');
  assert.ok(scene.events.filter(e=>context.LandscapeConfig.waterEvents.includes(e.type)).length<=2);
  for(const event of scene.events){
   seen.set(event.id,{...event,start:start+second*1000-event.age*1000});
   assert.ok(event.speed>=.82&&event.speed<=1.18);
  }
 }
 for(const event of seen.values())assert.ok(!timeline.at(event.start+event.duration*1000+.001).events.some(e=>e.id===event.id),'every finite visitor retires at its own complete exit');
 const shows=[...seen.values()].filter(e=>e.type==='fireworks').sort((a,b)=>a.start-b.start);
 assert.ok(shows.length>=2,'the deterministic private night includes repeated shows');
 for(let i=1;i<shows.length;i++)assert.ok(shows[i].start-shows[i-1].start>=4*(shows[i-1].duration+60)*1000-1,'the released sampled start interval is doubled again');
});

test('RISK pedestrian entry capacity: complete visitors retain fourteen admission reservations without eviction or seek-dependent admission',()=>{
 const context=sceneTimeline(),options={seed:'private-schedule',season:'summer',sunAt:()=>({altitude:-20,azimuth:0})};
 const timeline=context.LandscapeTimeline.create(options),clock=Date.parse('2026-10-06T01:24:56.116Z');
 const snapshot=scene=>JSON.parse(JSON.stringify(scene.events));
 for(const offset of [-1000,-1,0,1,7884,15884,60000,300000,-300000,0]){
  const at=clock+offset,scene=timeline.at(at);
  assertPedestrianReservationBound(scene);
  assert.deepEqual(snapshot(scene),snapshot(context.LandscapeTimeline.create({...options,width:390,height:844,reduced:true}).at(at)),'cold reload, viewport and motion choice reconstruct the same admitted visitors');
 }
 const before=timeline.at(clock-1),after=timeline.at(clock+15884);
 for(const event of before.events)if(event.age+15.885<event.duration){
  const retained=after.events.find(other=>other.id===event.id);
  assert.ok(retained,`capacity cannot evict underway ${event.id}`);
  assert.ok(Math.abs(retained.age-event.age-15.885)<1e-7);
  assert.equal(retained.duration,event.duration,'a crowded opportunity cannot shorten an admitted lifetime');
 }
});

test('RISK pedestrian capacity planner budget: cached daily scheduling evaluates each immutable proposal lifetime once',()=>{
 const context=sceneTimeline(),create=context.LandscapeGeometry.create,counts=new Map();
 context.LandscapeGeometry.create=(width,height)=>{const geometry=create(width,height);if(width===8192){const lifetime=geometry.walkingLifetime;geometry.walkingLifetime=event=>{counts.set(event.id,(counts.get(event.id)||0)+1);return lifetime(event);};}return geometry;};
 const timeline=context.LandscapeTimeline.create({seed:'private-schedule',season:'summer',sunAt:()=>({altitude:-20,azimuth:0})});
 timeline.at(Date.parse('2026-10-06T01:24:56.116Z'));
 timeline.at(Date.parse('2026-10-06T01:24:48Z'));timeline.at(Date.parse('2026-10-06T01:25:04Z'));
 assert.ok(counts.size>10,'the actual capacity history contains immutable proposals');
 assert.ok([...counts.values()].every(count=>count===1),`complete-life planning must not repeat inside quadratic overlap comparisons: ${JSON.stringify([...counts].filter(([,count])=>count!==1))}`);
});

test('RISK pedestrian capacity liveness: a busy day admits visitors while retaining bounded reservations and complete recipes',()=>{
 const context=sceneTimeline(),timeline=context.LandscapeTimeline.create({seed:'private-schedule',season:'summer',sunAt:()=>({altitude:30,azimuth:90})}),start=Date.parse('2026-10-06T01:00Z'),seen=new Set();
 for(let second=0;second<=1200;second+=30){const scene=timeline.at(start+second*1000);assertPedestrianReservationBound(scene);for(const event of scene.events)if(!['train','metro'].includes(event.type))seen.add(event.id);}
 assert.ok(seen.size>0,'dense opportunities must not reserve rejected visitors forever and starve all nonrail scenery');
});

test('RISK pedestrian capacity day boundary: admitted visits finish within their shared day while short late visitors remain possible',()=>{
 const context=sceneTimeline(),timeline=context.LandscapeTimeline.create({seed:'private-schedule',season:'summer',sunAt:()=>({altitude:30,azimuth:90})}),start=Date.parse('2026-10-06T23:40Z'),end=Date.parse('2026-10-07T00:00Z'),late=new Set();
 for(let at=start;at<=end;at+=30000){const scene=timeline.at(at);assertPedestrianReservationBound(scene);for(const event of scene.events){
  if(['train','metro'].includes(event.type))continue;
  const born=at-event.age*1000,dayEnd=(Math.floor(born/86400000)+1)*86400000;
  assert.ok(born+Math.max(event.duration,event.scheduleDuration||event.activityDuration||event.duration)*1000<=dayEnd+.001,'an admitted full reservation never needs truncation or midnight eviction');
  if(at<end&&event.age<=30)late.add(event.id);
 }}
 assert.ok(late.size>0,'the boundary guard is not a blanket pause before midnight');
});

