test("Landscape visitors: every arrival gets a starting speed and faster traffic can overtake", () => {
  const sky=livingSky(),geometryContext=vm.createContext({Math});
  vm.runInContext(fs.readFileSync(path.join(__dirname,'landscape-geometry.js'),'utf8'),geometryContext);
  const geometry=geometryContext.LandscapeGeometry.create(1000,700);
  assert.equal(typeof sky.startingSpeed,'function');
  const slowSpeed=sky.startingSpeed(0),fastSpeed=sky.startingSpeed(1);
  assert.ok(slowSpeed<1&&fastSpeed>1&&fastSpeed/slowSpeed>1.35,'the starting-speed range is noticeable but bounded');
  const slow={type:'plane',age:12,duration:100/slowSpeed,seed:.2,lane:.4,reverse:false};
  const fast={type:'plane',age:0,duration:100/fastSpeed,seed:.8,lane:.4,reverse:false};
  assert.ok(geometry.routeProgress(slow,'x')>geometry.routeProgress(fast,'x'),'the slower plane starts ahead');
  slow.age+=40;fast.age+=40;
  assert.ok(geometry.routeProgress(fast,'x')>geometry.routeProgress(slow,'x'),'the later, faster plane overtakes it');

  const world=sky.createWorld(()=>.25);
  assert.ok(world.events.length&&world.events.every(event=>event.speed>=slowSpeed&&event.speed<=fastSpeed),'ordinary and opening arrivals retain their assigned speed');
  const woodland=sky.createWoodland(()=>0);woodland.next=0;sky.advanceWoodland(woodland,1);
  assert.ok(woodland.events.length&&woodland.events.every(event=>event.speed>=slowSpeed&&event.speed<=fastSpeed),'woodland arrivals use the same speed contract');
});

test("Landscape: only one banner plane may be active while ordinary planes still overlap", () => {
  const sky = livingSky();
  const day = { sun: { altitude: 30, azimuth: 100 } };
  const slot = type => {
    const context=vm.createContext({Math});vm.runInContext(fs.readFileSync(path.join(__dirname,'landscape-config.js'),'utf8'),context);
    const entries=context.LandscapeConfig.pools.day,index=entries.findIndex(entry=>entry.type===type);
    assert.ok(index >= 0, `${type} must be an ordinary daytime event`);
    return (entries.slice(0,index).reduce((sum,entry)=>sum+entry.weight,0)+.1)/entries.reduce((sum,entry)=>sum+entry.weight,0);
  };
  const scheduled = (type, existingType, reverse = false) => {
    const world = sky.createWorld(() => .5);
    world.events = existingType ? [{ type: existingType, age: 0, duration: 10000, seed: .2, lane: .3, reverse: false }] : [];
    world.elapsed = 0;
    world.railNext = {train:Infinity,metro:Infinity}; // Isolate the ordinary flight schedule.
    world.next = 0;
    const values = [0, 1, slot(type), 0, .25, .25, reverse ? 1 : 0];
    let cursor = 0;
    world.random = () => values[cursor++] ?? .25;
    sky.advance(world, 1, day);
    return world;
  };

  const banner = scheduled("banner", "banner", true);
  assert.equal(banner.events.filter(event => event.type === "banner").length, 1,
    "a second banner is suppressed while the first is still in flight");

  const planes = scheduled("plane", "plane");
  assert.ok(planes.events.filter(event => event.type === "plane").length >= 2,
    "ordinary planes remain allowed to overlap");

  const forward = scheduled("banner", null, false).events.find(event => event.type === "banner");
  const reverse = scheduled("banner", null, true).events.find(event => event.type === "banner");
  assert.equal(forward.reverse, false);
  assert.equal(reverse.reverse, true);
});

test("Landscape: shooting stars are brief, night-only, and singly bounded", () => {
  const sky = livingSky();
  assert.ok(sky.nightEventTypes.includes("meteor"), "meteor is a declared night visitor");
  assert.ok(sky.eventDurations.meteor < 3, "shooting stars stay brief");
  const schedule = altitude => {
    const world = sky.createWorld(() => .5);
    world.events = [];
    world.elapsed = 0;
    world.railNext = {train:Infinity,metro:Infinity}; // Isolate the ordinary flight schedule.
    world.next = 0;
    world.lastRare = 0;
    world.random = () => 0;
    for (let i = 0; i < 24; i++) {
      world.next = world.elapsed;
      sky.advance(world, .25, { sun: { altitude, azimuth: 100 } });
      assert.ok(world.events.filter(event => event.type === "meteor").length <= 1,
        "the night sky has at most one shooting star at a time");
    }
    return world;
  };
  assert.equal(schedule(30).events.filter(event => event.type === "meteor").length, 0,
    "daytime scheduling never emits shooting stars");
  assert.ok(schedule(-20).events.some(event => event.type === "meteor"),
    "night scheduling eventually emits a shooting star");
});

test("Landscape browser: first launch, motion lifecycle, theme independence and return navigation", {
  skip:!process.env.LANDSCAPE_BROWSER_URL
}, async () => {
  const {chromium}=await import(process.env.LANDSCAPE_PLAYWRIGHT);
  const browser=await chromium.launch({headless:true,channel:process.env.LANDSCAPE_BROWSER_CHANNEL||"chrome"});
  try{
    const page=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:3,reducedMotion:"no-preference"});
    await page.clock.setFixedTime(new Date("2026-09-12T15:00:00Z"));
    const errors=[];page.on("pageerror",error=>errors.push(error.message));
    await page.addInitScript(()=>{
      window.lifePaints=0;
      const clear=CanvasRenderingContext2D.prototype.clearRect;
      CanvasRenderingContext2D.prototype.clearRect=function(...args){if(this.canvas.hasAttribute('data-life'))window.lifePaints++;return clear.apply(this,args);};
    });
    await page.goto(process.env.LANDSCAPE_BROWSER_URL,{waitUntil:"networkidle"});
    assert.equal(await page.locator('#motionDialog').evaluate(e=>e.open),true);
    await page.locator('button[data-landscape-motion="reduced"]').click();
    await page.waitForTimeout(50);
    assert.equal(await page.evaluate(()=>!!document.activeElement.closest('#modalRoot')),true,"choice restores focus to the still-open first-run help");
    await page.locator('#modalRoot [data-act="close-modal"]').click();
    await page.locator('#addInput').fill('Keep this task during scenery controls');
    await page.locator('[data-act="add"]').click();
    await page.locator('[data-act="start-scan"]').click();
    const tasksBefore=await page.evaluate(()=>JSON.stringify(state.tasks));
    const still=await page.evaluate(()=>lifePaints);await page.waitForTimeout(250);
    assert.equal(await page.evaluate(()=>lifePaints),still,"reduced motion has no frame loop");
    await page.locator('#motionButton').click();await page.keyboard.press('Delete');
    assert.equal(await page.evaluate(()=>JSON.stringify(state.tasks)),tasksBefore,'motion dialog blocks scanner shortcuts');
    await page.locator('button[data-landscape-motion="normal"]').click();
    const moving=await page.evaluate(()=>lifePaints);await page.waitForTimeout(300);
    assert.ok(await page.evaluate(()=>lifePaints)>moving,"normal mode continuously paints life");
    await page.emulateMedia({reducedMotion:"reduce"});await page.waitForTimeout(60);
    const stopped=await page.evaluate(()=>lifePaints);await page.waitForTimeout(250);
    assert.equal(await page.evaluate(()=>lifePaints),stopped,"live OS reduction stops the loop");
    await page.emulateMedia({reducedMotion:"no-preference"});
    await page.evaluate(()=>{window.dispatchEvent(new Event('resize'));Object.defineProperty(document,'hidden',{configurable:true,value:true});document.dispatchEvent(new Event('visibilitychange'));});
    const hidden=await page.evaluate(()=>lifePaints);await page.waitForTimeout(250);
    assert.equal(await page.evaluate(()=>lifePaints),hidden,"hidden tabs do not animate");
    await page.evaluate(()=>{Object.defineProperty(document,'hidden',{configurable:true,value:false});document.dispatchEvent(new Event('visibilitychange'));});
    await page.waitForTimeout(200);assert.ok(await page.evaluate(()=>lifePaints)>hidden);
    const background=await page.locator('[data-scenery]').evaluate(c=>c.toDataURL());
    const chromeColor=await page.locator('meta[name="theme-color"]').getAttribute('content');
    await page.locator('#themeBtn').click();await page.locator('#themeBtn').click();
    assert.notEqual(await page.locator('meta[name="theme-color"]').getAttribute('content'),chromeColor,'browser chrome follows the independent UI theme');
    assert.equal(await page.locator('[data-scenery]').evaluate(c=>c.toDataURL()),background,"theme changes do not repaint the real sky");
    await page.locator('#viewScene').click();assert.equal(await page.locator('.wrap').evaluate(e=>e.inert),true);
    await page.keyboard.press('Delete');assert.equal(await page.evaluate(()=>JSON.stringify(state.tasks)),tasksBefore,'scenery view blocks scanner shortcuts');
    await page.locator('#exitScene').click();assert.equal(await page.locator('.wrap').evaluate(e=>e.inert),false);
    assert.equal(await page.evaluate(()=>document.activeElement.id),'viewScene');
    await page.reload({waitUntil:"networkidle"});
    assert.equal(await page.locator('#motionDialog').evaluate(e=>e.open),false,"motion choice survives reload");
    assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);
    await page.setViewportSize({width:2560,height:1080});await page.waitForTimeout(200);
    assert.ok(await page.locator("[data-scenery]").evaluate(c=>c.width*c.height<=3000000),"high-DPR canvas stays within its pixel budget");
    assert.deepEqual(errors,[]);
  }finally{await browser.close();}
});

test("Landscape: device motion preference fails safely and OS reduction always wins", () => {
  const sky=livingSky();
  assert.equal(sky.motionReduced("normal",true),true);
  assert.equal(sky.motionReduced("reduced",false),true);
  assert.equal(sky.motionReduced("normal",false),false);
  assert.equal(sky.motionReduced(null,false),true, "no movement before first-launch consent");
  assert.equal(sky.readMotion({getItem(){throw Error("blocked")}}),null);
  assert.equal(sky.readMotion({getItem(){return "garbage"}}),null);
  let saved;
  assert.equal(sky.saveMotion({setItem(k,v){saved=v}},"normal"),true);
  assert.equal(JSON.parse(saved).choice,"normal");
  assert.equal(sky.saveMotion({setItem(){throw Error("quota")}},"reduced"),false);
});

test('RISK motion safety: explicit local choices expire after seven elapsed days and corrupt records fail closed',()=>{
 const sky=livingSky(),now=2000000000000,week=7*24*60*60*1000,data=new Map();
 const storage={getItem:key=>data.get(key)??null,setItem:(key,value)=>data.set(key,value)};
 for(const choice of ['normal','reduced']){
  assert.equal(sky.saveMotion(storage,choice,now),true);
  assert.equal(sky.readMotion(storage,now),choice);
  assert.equal(sky.readMotion(storage,now+week-1),choice);
  assert.equal(sky.readMotion(storage,now+week),null,'exact seven-day boundary asks again');
  assert.equal(sky.readMotion(storage,now-1),null,'future timestamps do not consent');
 }
 for(const value of ['normal','reduced','{}','null','{"choice":"normal","savedAt":"2000000000000"}','{"choice":"normal","savedAt":-1}','{"choice":"invalid","savedAt":2000000000000}']){
  data.set('fvp:chain-scanner:landscape-motion',value);
  assert.equal(sky.readMotion(storage,now),null,'legacy or corrupt value requires explicit choice');
 }
 assert.equal(sky.saveMotion(storage,'invalid',now),false);
 assert.equal(sky.motionReduced(sky.readMotion(storage,now),false),true);
 assert.equal(sky.motionReduced('normal',true),true);
});

test('RISK motion safety: actual choice handler remembers selection while dismissal never writes consent',()=>{
 const source=fs.readFileSync(path.join(__dirname,'landscape.js'),'utf8'),calls=[];
 const choice=source.slice(source.indexOf('    preference=button.dataset.landscapeMotion;'),source.indexOf("  dialog.addEventListener('close'"));
 const body=choice.slice(0,choice.lastIndexOf('  });'));
 const run=new Function('button','S','storage','updateMotion','dialog','let preference=null;'+body+';return preference;');
 const sky=livingSky(),data=new Map(),storage={getItem:k=>data.get(k)??null,setItem:(k,v)=>data.set(k,v)};
 assert.equal(run({dataset:{landscapeMotion:'reduced'}},sky,storage,()=>calls.push('update'),{close:()=>calls.push('close')}),'reduced');
 assert.equal(sky.readMotion(storage),'reduced','reload sees the explicit selection');
 const cancel=source.match(/dialog\.addEventListener\('cancel',\(\)=>\{([\s\S]*?)\n  \}\);/)[1];
 new Function('S','storage','updateMotion','let preference=null;'+cancel)(sky,{setItem(){throw Error('dismiss must not save')}},()=>{});
 assert.doesNotMatch(cancel,/saveMotion/,'dismissal leaves no remembered choice');
 assert.deepEqual(calls,['update','close']);
});

test("Landscape: local assets, decorative layers and accessible motion controls are integrated", () => {
  for(const file of ["landscape.css","landscape-core.js","landscape.js","stars.js","vendor/astronomy.min.js"]){
    assert.ok(html.includes(file), `HTML must load ${file}`);
    assert.ok(serviceWorkerSource().includes(`./${file}`), `offline cache must include ${file}`);
  }
  assert.match(html, /id="landscape"[^>]*aria-hidden="true"/);
  assert.match(html, /id="motionDialog"/);
  assert.match(html, /data-landscape-motion/);
  assert.match(html, /data-act="scene-settings"/);
  assert.match(html, /id="sceneStatus"/);
  const runtime=fs.readFileSync(path.join(__dirname,"landscape.js"),"utf8");
  // Authored copy is a precached local asset; no external runtime services.
  const withoutLocalCopy = runtime.replace("fetch('./HUMAN_WRITTEN_HOURLY_TAGS.md')", 'localCopy').replace("fetch('./SPAWN_RATES.md')", 'localRates');
  assert.doesNotMatch(withoutLocalCopy,/\b(?:fetch|XMLHttpRequest|WebSocket)\s*\(/);
  assert.match(runtime,/visibilitychange/);
  assert.match(runtime,/cancelAnimationFrame/);
  assert.match(runtime,/prefers-reduced-motion/);
});

test("PWA contract: links a valid manifest with install metadata and required icons", () => {
  const href = manifestHrefFromHtml();
  const manifestPath = path.resolve(__dirname, href);
  assert.ok(manifestPath.startsWith(`${__dirname}${path.sep}`), "manifest must stay inside the app repository");
  assert.ok(fs.existsSync(manifestPath), `manifest file must exist: ${href}`);

  let manifest;
  assert.doesNotThrow(() => { manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8")); },
    "manifest must contain valid JSON");
  for (const field of ["name", "short_name", "start_url", "display", "theme_color", "background_color"]) {
    assert.equal(typeof manifest[field], "string", `manifest.${field} must be a string`);
    assert.ok(manifest[field].trim(), `manifest.${field} must not be empty`);
  }
  assert.ok(["standalone", "fullscreen", "minimal-ui", "browser"].includes(manifest.display),
    "manifest.display must be a recognized display mode");
  assert.ok(Array.isArray(manifest.icons), "manifest.icons must be an array");
  for (const size of ["192x192", "512x512"]) {
    const icon = manifest.icons.find((entry) => entry.sizes === size && typeof entry.src === "string" && entry.src.trim());
    assert.ok(icon, `manifest must provide a non-empty ${size} icon`);
    const iconPath = path.resolve(path.dirname(manifestPath), icon.src);
    assert.ok(iconPath.startsWith(`${__dirname}${path.sep}`), `${size} icon must stay inside the app repository`);
    assert.ok(fs.existsSync(iconPath), `${size} icon file must exist: ${icon.src}`);
    const png = fs.readFileSync(iconPath);
    assert.deepEqual([...png.subarray(0, 8)], [137, 80, 78, 71, 13, 10, 26, 10], `${size} icon must be a PNG`);
    assert.equal(png.readUInt32BE(16), Number(size.slice(0, 3)), `${size} icon must have the declared width`);
    assert.equal(png.readUInt32BE(20), Number(size.slice(0, 3)), `${size} icon must have the declared height`);
  }
});

