test("smoke: engine extracts and phi/Phi behave like a real CDF", () => {
  const E = loadEngine();
  assert.ok(Math.abs(E.Phi(0) - 0.5) < 0.01, "Phi(0) should be ~0.5");
  assert.ok(E.Phi(-10) < 0.001, "Phi(-10) should be ~0");
  assert.ok(E.Phi(10) > 0.999, "Phi(10) should be ~1");
});

test("Phi is monotonically increasing", () => {
  const E = loadEngine();
  const xs = [-5, -2, -1, -0.5, 0, 0.5, 1, 2, 5];
  for (let i = 1; i < xs.length; i++) {
    assert.ok(E.Phi(xs[i]) >= E.Phi(xs[i - 1]), `Phi(${xs[i]}) should be >= Phi(${xs[i - 1]})`);
  }
});

test("pBeats and pJudged are complementary under swap (proper CDF symmetry)", () => {
  const E = loadEngine();
  const a = { mu: 30, sigma: 5 }, b = { mu: 22, sigma: 6 };
  assert.ok(Math.abs(E.pBeats(a, b) + E.pBeats(b, a) - 1) < 1e-9);
  assert.ok(Math.abs(E.pJudged(a, b) + E.pJudged(b, a) - 1) < 1e-9);
});

test("pJudged is exactly 0.5 for identical strengths", () => {
  const E = loadEngine();
  const a = { mu: 25, sigma: 8 }, b = { mu: 25, sigma: 8 };
  assert.ok(Math.abs(E.pJudged(a, b) - 0.5) < 1e-9);
});

test("updatePair: winner's mu rises, loser's mu falls", () => {
  const E = loadEngine();
  const winner = { mu: 25, sigma: 25 / 3 };
  const loser = { mu: 25, sigma: 25 / 3 };
  E.updatePair(winner, loser);
  assert.ok(winner.mu > 25, "winner mu should increase");
  assert.ok(loser.mu < 25, "loser mu should decrease");
});

test("updatePair: sigma never drops below SIGMA_FLOOR, even after many updates", () => {
  const E = loadEngine();
  const floor = readConst(E, "SIGMA_FLOOR");
  const a = { mu: 25, sigma: 25 / 3 };
  const b = { mu: 20, sigma: 25 / 3 };
  for (let i = 0; i < 200; i++) E.updatePair(a, b);
  assert.ok(a.sigma >= floor - 1e-9);
  assert.ok(b.sigma >= floor - 1e-9);
});

test("rankStats: single item always ranks 1st with full probability mass", () => {
  const E = loadEngine(1);
  const stats = E.rankStats([{ id: "only", mu: 25, sigma: 5 }], 200);
  const st = stats.get("only");
  assert.equal(st.topK, 1);
  assert.ok(Math.abs(st.hist[0] - 1) < 1e-6);
});

test("rankStats: a dominant item (huge mu, tiny sigma) wins rank 1 almost always", () => {
  const E = loadEngine(42);
  const items = [
    { id: "dominant", mu: 1000, sigma: 0.1 },
    { id: "weak1", mu: 25, sigma: 8 },
    { id: "weak2", mu: 20, sigma: 8 },
    { id: "weak3", mu: 15, sigma: 8 },
  ];
  const stats = E.rankStats(items, 500);
  const dom = stats.get("dominant");
  assert.ok(dom.hist[0] > 0.98, `expected dominant item to hold rank 1 nearly always, got P(rank=1)=${dom.hist[0]}`);
  // topK is defined (see the ENGINE comment) as the smallest K >= 2 with P(rank<=K) >= 1-1/K —
  // it never checks K=1 by construction, so 2 is the best a dominant item can score, not 1.
  assert.equal(dom.topK, 2);
});

test("rankStats: probability mass sums to 1 per item and topK is within bounds", () => {
  const E = loadEngine(7);
  const items = [
    { id: "a", mu: 30, sigma: 5 }, { id: "b", mu: 25, sigma: 6 },
    { id: "c", mu: 20, sigma: 7 }, { id: "d", mu: 15, sigma: 8 },
  ];
  const stats = E.rankStats(items, 300);
  for (const it of items) {
    const st = stats.get(it.id);
    const sum = st.hist.reduce((a, b) => a + b, 0);
    assert.ok(Math.abs(sum - 1) < 1e-6, `hist for ${it.id} should sum to 1, got ${sum}`);
    assert.ok(st.topK >= 1 && st.topK <= items.length);
  }
});

test("thompsonPick: empty pool returns null, single-item pool returns that item", () => {
  const E = loadEngine(3);
  assert.equal(E.thompsonPick([]), null);
  const only = { id: "x", mu: 10, sigma: 2 };
  assert.equal(E.thompsonPick([only]), only);
});

test("thompsonPick: a low-variance, much-stronger item is picked in the large majority of draws", () => {
  const E = loadEngine(99);
  const strong = { id: "strong", mu: 500, sigma: 0.5 };
  const weak = { id: "weak", mu: 25, sigma: 8 };
  let strongCount = 0;
  const trials = 500;
  for (let i = 0; i < trials; i++) {
    if (E.thompsonPick([strong, weak]).id === "strong") strongCount++;
  }
  assert.ok(strongCount / trials > 0.95, `expected the dominant item picked >95% of the time, got ${strongCount}/${trials}`);
});

test("chanceBetterSoon: empty pool is always 0", () => {
  const E = loadEngine();
  assert.equal(E.chanceBetterSoon({ mu: 25, sigma: 5 }, [], 5), 0);
});

test("chanceBetterSoon: exactly 0.5 for one equal-strength candidate (deterministic, no RNG involved)", () => {
  const E = loadEngine();
  const bench = { mu: 25, sigma: 8 };
  const pool = [{ mu: 25, sigma: 8 }];
  const chance = E.chanceBetterSoon(bench, pool, 1);
  assert.ok(Math.abs(chance - 0.5) < 1e-9, `expected exactly 0.5, got ${chance}`);
});

test("chanceBetterSoon: rises toward 1 as the pool has more equally-strong candidates", () => {
  const E = loadEngine();
  const bench = { mu: 25, sigma: 8 };
  const pool3 = [{ mu: 25, sigma: 8 }, { mu: 25, sigma: 8 }, { mu: 25, sigma: 8 }];
  const chance1 = E.chanceBetterSoon(bench, pool3, 1);
  const chance3 = E.chanceBetterSoon(bench, pool3, 3);
  assert.ok(chance3 > chance1, "considering more candidates per minute should raise the chance of finding a better one");
});

test("RISK TrueSkill probability: answer judgments use the same performance noise as rank updates", () => {
  const E = loadEngine();
  const a = { mu: 29, sigma: 4 }, b = { mu: 21, sigma: 7 };
  assert.equal(E.pJudged(a, b), E.pBeats(a, b),
    "one Yes/No answer and one rank update must use the same BETA performance-noise model");
});

test("RISK chance forecast: five candidates share one uncertain benchmark draw", () => {
  const E = loadEngine();
  const bench = { mu: 25, sigma: 25 / 3 };
  const pool = Array.from({ length: 5 }, () => ({ mu: 25, sigma: 0.8 }));
  const chance = E.chanceBetterSoon(bench, pool, 5);
  // Independent reference: a 256-panel Simpson integral over the shared
  // benchmark performance, with Python math.erfc for the conditional normal CDF.
  assert.ok(Math.abs(chance - 0.6934877295879022) < 2e-6,
    `five candidates should share benchmark uncertainty; got ${chance}`);
  assert.ok(chance < 0.75, "the benchmark's one shared uncertain score cannot be counted as five independent draws");
});

test("RISK chance forecast: one-candidate marginal and supplied order stay intact", () => {
  const E = loadEngine();
  const bench = { mu: 25, sigma: 5 };
  const first = { id: "first", mu: 20, sigma: 2 };
  const later = { id: "later", mu: 40, sigma: 2 };
  const single = E.chanceBetterSoon(bench, [later], 1);
  assert.ok(Math.abs(single - E.pBeats(later, bench)) < 2e-7,
    "with one candidate, the shared-performance integral equals the existing match probability");
  const ordered = E.chanceBetterSoon(bench, [first, later], 1);
  assert.ok(Math.abs(ordered - E.pBeats(first, bench)) < 2e-7,
    "the forecast uses the first candidate in the caller's actual queue order");
  assert.ok(ordered < single, "a later strong candidate must not be forecast ahead of the first task");
});

test("RISK chance forecast: one candidate matches pBeats across extreme supported uncertainty ratios", () => {
  const E = loadEngine();
  const bench = { mu: -50, sigma: 1000 };
  const candidate = { mu: -100, sigma: 0.8 };
  const chance = E.chanceBetterSoon(bench, [candidate], 1);
  assert.equal(chance, E.pBeats(candidate, bench),
    "the one-candidate forecast is exactly the existing match probability, even when the shared draw is much broader");
});

test("RISK chance forecast: adaptive integration resolves narrow shared-benchmark transitions", () => {
  const E = loadEngine();
  // Independent references use Python math.erfc with adaptive Simpson split
  // around each candidate's conditional-CDF transition.
  const cases = [
    {
      bench: { mu: -50, sigma: 1000 },
      pool: [{ mu: -100, sigma: 0.8 }, { mu: -55, sigma: 0.8 }],
      expected: 0.49800533217659593
    },
    {
      bench: { mu: 0, sigma: 10000 },
      pool: [{ mu: -5000, sigma: 0.8 }, { mu: 5000, sigma: 0.8 }],
      expected: 0.69146243014948894
    }
  ];
  for (const { bench, pool, expected } of cases) {
    const chance = E.chanceBetterSoon(bench, pool, 2);
    assert.ok(Math.abs(chance - expected) < 2e-8,
      `shared benchmark integral should match the independent high-precision reference; got ${chance}, expected ${expected}`);
  }
});

test("RISK TrueSkill truncation: inverse-Mills tails match references through the former cutoff and extreme upset", () => {
  const E = loadEngine();
  const cases = [
    [-5.999, 6.157506595658616, 0.9760054082233257],
    [-6, 6.158482604544579, 0.9760123632107078],
    [-6.001, 6.159458620384075, 0.9760193152988542],
    [-10, 10.09809323396242, 0.9905546221734387],
    [-25, 25.039873012055, 0.9984151584653532],
  ];
  for (const [t, expectedV, expectedW] of cases) {
    const actual = E.truncGaussVW(t);
    assert.ok(Math.abs(actual.v - expectedV) < 2e-8, `v(${t}) should match the stable normal-tail reference, got ${actual.v}`);
    assert.ok(Math.abs(actual.w - expectedW) < 2e-9, `w(${t}) should match the stable normal-tail reference, got ${actual.w}`);
  }
  const atCutoff = E.truncGaussVW(-6);
  const justAbove = E.truncGaussVW(-5.999);
  const justBelow = E.truncGaussVW(-6.001);
  assert.ok(Math.abs(atCutoff.v - (justAbove.v + justBelow.v) / 2) < 2e-6,
    "the former denominator switch must not create a discontinuous jump in v");
  const extreme = E.truncGaussVW(-80);
  assert.ok(Number.isFinite(extreme.v) && Number.isFinite(extreme.w));
  assert.ok(extreme.v > 80 && extreme.w > 0.999 && extreme.w < 1,
    "an extreme upset keeps the finite, nonzero Gaussian tail correction");
});

test("RISK rating bounds: hydration and frozen chance opponents normalize extremes without changing healthy ratings", async () => {
  const { ctx } = await loadApp();
  const muLimit = readConst(ctx, "RATING_MU_LIMIT");
  const sigmaLimit = readConst(ctx, "RATING_SIGMA_LIMIT");
  const sigmaFloor = readConst(ctx, "SIGMA_FLOOR");
  const board = structuredClone(ctx.state);
  board.v = 2;
  board.tasks = [
    { id: "healthy", title: "Healthy", mu: 37.25, sigma: 1.125, createdAt: 1, ctx: [] },
    { id: "huge", title: "Huge", mu: 1e200, sigma: 1e200, createdAt: 2, ctx: [] },
    { id: "invalid", title: "Invalid", mu: NaN, sigma: 0, createdAt: 3, ctx: [] },
  ];
  board.chance = {
    seed: "same-frozen-pass", at: 1, weights: {},
    opponents: [{ id: "frozen-huge", mu: -1e200, sigma: 1e200 }],
  };
  board.scanMode = "chance";
  ctx.hydrateState(board);

  assert.deepEqual([board.tasks[0].mu, board.tasks[0].sigma], [37.25, 1.125],
    "ordinary saved ratings keep their exact values");
  assert.deepEqual([board.tasks[1].mu, board.tasks[1].sigma], [muLimit, sigmaLimit]);
  assert.deepEqual([board.tasks[2].mu, board.tasks[2].sigma], [readConst(ctx, "PRIOR_MU"), readConst(ctx, "PRIOR_SIGMA")]);
  assert.deepEqual([board.chance.opponents[0].mu, board.chance.opponents[0].sigma], [-muLimit, sigmaLimit]);
  assert.equal(board.chance.seed, "same-frozen-pass", "rating repair keeps the already-frozen pass identity");

  const winner = { mu: 1e200, sigma: 1e200 };
  const loser = { mu: -1e200, sigma: 1e200 };
  ctx.updatePair(winner, loser);
  for (const value of [winner.mu, winner.sigma, loser.mu, loser.sigma]) assert.ok(Number.isFinite(value));
  assert.ok(Math.abs(winner.mu) <= muLimit && Math.abs(loser.mu) <= muLimit);
  assert.ok(winner.sigma >= sigmaFloor && winner.sigma <= sigmaLimit);
  assert.ok(loser.sigma >= sigmaFloor && loser.sigma <= sigmaLimit);
});

// #2303 (owner spec #2298 and decisions of 2026-11-09): the Data section is, in
// order, one status line, Make backup, Download backup, Restore, the backup
// list, a closed Troubleshooting section and Reset everything. Housekeeping is
// gone; Clear history stays in the History panel.
test("RISK Data and backups layout: one status line, Make backup, Download backup, Restore, the backup list, closed Troubleshooting and Reset everything, with Clear history only in History", async () => {
  const { ctx, shim } = await loadApp();
  const done = ctx.addTask("Finished layout task", false); ctx.addTask("Open layout task", false);
  ctx.state.chain = [done.id]; ctx.pushUndo(); ctx.completeTask(done); await ctx.persist();
  ctx.onAction("make-manual-backup", {}); for (let i = 0; i < 50 && !ctx.readLocalBackups().some(row => row.kind === "manual"); i++) await flush();
  ctx.openSettings();
  const markup = shim.document.getElementById("modalRoot").innerHTML;
  const data = markup.split("<summary>Data and backups</summary>")[1] || "";
  assert.ok(data, "positive control: Settings has Data and backups");
  assert.equal((data.match(/class="statusdot"/g) || []).length, 1, "one status line");
  const order = [/class="statusdot"/, /data-act="make-manual-backup">Make backup</, /data-act="download-recovery-file">Download backup</,
    /data-act="restore-backup"[^>]*>Restore</, /class="mgr backup-row"/, /<details class="settings-troubleshooting"><summary>Troubleshooting<\/summary>/,
    /data-act="wipe">Reset everything</];
  const at = order.map(pattern => data.search(pattern));
  assert.ok(at.every(index => index >= 0), "every item is in the Data section: " + JSON.stringify(at));
  assert.deepEqual(at.slice().sort((a, b) => a - b), at, "the items appear in the approved order: " + JSON.stringify(at));
  const troubleshooting = data.split('<details class="settings-troubleshooting">')[1]?.split("</details>")[0] || "";
  assert.match(troubleshooting, /data-act="view-support-diagnostics">View debug log</, "Troubleshooting holds the Debug log");
  assert.match(troubleshooting, /data-act="review-decision-recovery">Review saved decisions</, "Troubleshooting holds Review saved decisions");
  assert.doesNotMatch(markup, /<details class="settings-troubleshooting" open/, "Troubleshooting is closed when Settings opens");
  assert.doesNotMatch(markup, /Housekeeping|data-act="clear-done"|History panel/, "Settings no longer repeats Clear history");
  ctx.closeModal(); ctx.state.histOpen = true; ctx.render();
  assert.match(shim.document.getElementById("histPanel").innerHTML, /data-act="clear-done">Clear history</, "Clear history stays in the History panel");
});

