   if(injected||!reference.includes('/chunks/')||docs.get(reference.split('/chunks/')[0])?.state!=='staging')return;
   injected=true;if(change==='account')h.emitAuth({uid:'other-owner',email:'other@example.test'});else h.CS.suspend();
