test('RISK LOCAL BACKUPS: full optional history cannot block an ordinary edit that fits primary storage',async()=>{
 const values=new Map(),used=()=>[...values].reduce((sum,[key,value])=>sum+key.length+value.length,0);
 let quota=Infinity;
 const storage={
  getItem:key=>values.get(key)??null,
  setItem:(key,value)=>{
   const next=String(value),prior=values.get(key)||'';
   if(used()-prior.length+next.length>quota){const error=Error('site quota');error.name='QuotaExceededError';throw error;}
   values.set(key,next);
  },
  removeItem:key=>values.delete(key),
 };
 const {ctx,shim}=await loadApp({sharedStorage:storage});
 ctx.addTask('Saved task');assert.equal(await ctx.persist(),true);
 const before=storage.getItem(SYNC_STORE_KEY),at=Date.now(),day=ctx.backupDay(at);
 const archive=Array.from({length:6},(_,i)=>({id:'manual-'+i,day,at:at-i,kind:'manual',payload:before}));
 storage.setItem(LOCAL_BACKUPS_KEY,JSON.stringify(archive));
 ctx.state.tasks[0].title='Saved task with an ordinary new edit';
 const after=JSON.stringify(ctx.state),growth=(after.length-before.length)*2;
 quota=used()+growth+32; // both primary replacements fit; another full-board history row cannot
 assert.equal(await ctx.persist(),true,'optional backup quota must not hold a primary edit: '+(shim.document.getElementById('toast')?.textContent||''));
 assert.equal(storage.getItem(SYNC_STORE_KEY),after);
 assert.equal(storage.getItem(LOCAL_HEAD_KEY),after);
 assert.ok(ctx.parseBackupIndex(storage.getItem(LOCAL_BACKUPS_KEY)).filter(row=>row.kind==='manual').length===archive.length);
 assert.doesNotMatch(shim.document.getElementById('toast')?.textContent||'',/remove an old manual backup/);
 const reopened=await loadApp({sharedStorage:storage});
 assert.equal(reopened.ctx.state.tasks[0].title,'Saved task with an ordinary new edit');
 quota=Infinity;
 reopened.ctx.state.tasks[0].title='Another edit after space returns';
 assert.equal(await reopened.ctx.persist(),true);
 assert.ok(reopened.ctx.parseBackupIndex(storage.getItem(LOCAL_BACKUPS_KEY)).some(row=>row.kind==='latest'&&row.payload===JSON.stringify(reopened.ctx.state)),
  'automatic history resumes on a later save when storage has room');
});

test('RISK LOCAL BACKUPS: async host Restore rolls back if its safety row disappears',async()=>{
 const prior=JSON.stringify(syncState({tasks:[syncTask('prior-host','Prior host board')]}));
 const {ctx,shim}=await loadApp({hostStorage:{[SYNC_STORE_KEY]:prior}});
 const target=JSON.stringify(syncState({tasks:[syncTask('restored-host','Restored huge '.repeat(50).trim())]}));
 assert.equal(ctx.saveLocalBackup('manual',target),true);
 const backup=ctx.readLocalBackups().find(row=>row.kind==='manual' && row.payload===target);
 const set=shim.window.storage.set.bind(shim.window.storage);
 let release;
 shim.window.storage.set=async(key,payload)=>{
  await set(key,payload);
  if(key===SYNC_STORE_KEY && payload.includes('Restored huge')) await new Promise(resolve=>{release=resolve;});
 };
 ctx.openSettings();const restore=ctx.restoreDurableBackupById(backup.id);
 await flush();
 assert.equal(typeof release,'function','the host primary write is awaiting its asynchronous acknowledgement');
 const rows=JSON.parse(shim.localStorage.getItem(LOCAL_BACKUPS_KEY));
 const safety=rows.find(row=>row.kind==='before-restore' && row.payload.includes('Prior host board'));
 assert.ok(safety);
 shim.localStorage.setItem(LOCAL_BACKUPS_KEY,JSON.stringify(rows.filter(row=>row.id!==safety.id)));
 release();await restore;await flush();await flush();
 assert.equal(shim.window.storage._map.get(SYNC_STORE_KEY),prior,
  'a changed backup index rolls back this host write rather than accepting an unprotected Restore');
 assert.equal(vm.runInContext('pendingRestoreSafetyIds.size',ctx),1,
  'the pending recovery proof remains until a protected primary write succeeds');
});

