test("CSS: '.listwrap' carries the same margin-top as its '.addwrap'/'.histwrap' siblings", () => {
  // listWrap used to be the first panel after #scan, which already supplied
  // the gap via its own margin-bottom — so .listwrap never needed a
  // margin-top of its own. Now that addPanel sits between #scan and
  // listWrap, listWrap needs the same spacing rule its stacked siblings use,
  // or the add panel and the list below it butt up with no gap.
  const m = html.match(/\.listwrap\{([^}]*)\}/);
  assert.ok(m, ".listwrap rule exists");
  assert.match(m[1], /margin-top:\s*14px/, ".listwrap has margin-top:14px, matching .addwrap/.histwrap");
});

/* ---- H5: every row claims the dot that only one row gets ----
   renderList() draws the "→" marker on every row whenever the chain is empty,
   and its tooltip says "Will be added to the chain when you start scanning".
   startScan() dots exactly one task: the oldest outstanding one. */
test("AUDIT H5: with nothing dotted, only the task Start scanning will dot carries the '→' marker", async () => {
  const { ctx } = await loadApp({ seed: 8005 });
  const a = ctx.addTask("Oldest", false);
  const b = ctx.addTask("Middle", false);
  const c = ctx.addTask("Newest", false);
  // addTask stamps createdAt off the clock and three adds can share a
  // millisecond — pin them so "oldest" is unambiguous.
  ctx.state.tasks.find((t) => t.id === a.id).createdAt = 1000;
  ctx.state.tasks.find((t) => t.id === b.id).createdAt = 2000;
  ctx.state.tasks.find((t) => t.id === c.id).createdAt = 3000;
  ctx.state.listOpen = true;
  ctx.render();

  const html = ctx.document.getElementById("listBody").innerHTML;
  const marks = html.split("chainind").length - 1;
  assert.equal(marks, 1,
    `the marker promises the dot to one task; ${marks} of ${ctx.state.tasks.length} rows claim it`);

  const rowOf = (id) => html.split('data-row="').find((chunk) => chunk.startsWith(id)) || "";
  assert.ok(rowOf(a.id).includes("chainind"), "and it belongs to the oldest outstanding task");
  ctx.startScan('descending');
  // Array.from: this chain was built by defaultState() inside the vm context,
  // so it carries that realm's Array.prototype and deepStrictEqual would
  // reject it against an outer-realm literal however equal the contents are.
  assert.deepEqual(Array.from(ctx.state.chain), [a.id],
    "...which is the one Start scanning actually dots");
});

/* ---- H6: one settings fallback still points at the retired default ----
   DEFAULT_SETTINGS is documented as the single source of truth for "what a
   fresh install gets" and "what a backfill gets". save-settings hardcodes its
   own fallbacks; four match, workedHours does not — it still falls back to 8,
   the exact value the v2 migration exists to move people off, and once saved
   the migration will not run again to correct it. */
test("AUDIT H6: a cleared 'worked on it' field falls back to the current default, not the retired 8", async () => {
  const { ctx } = await loadApp({ seed: 8006 });
  // #2303: cleared the box and left it; there is no Save settings button.
  const field = commitSetting(ctx, "stWorkedHrs", "");

  const DEFAULTS = readConst(ctx, "DEFAULT_SETTINGS");
  assert.equal(ctx.state.settings.workedHours, DEFAULTS.workedHours,
    "a cleared field keeps the current value, which on a fresh board is DEFAULT_SETTINGS, not the retired 8");
  assert.equal(field.value, String(DEFAULTS.workedHours), "and the box shows that value again");
});

/* ---- H7: a dot pointing at nothing strands the scan ----
   benchmark() resolves the last chain entry through taskById(), which answers
   null for an id with no task behind it. chainStart() is still false, so a
   candidate is dealt and the "Would I rather…" question renders — but decide()
   refuses yes/no without a benchmark, so both buttons fall straight out and
   the scan cannot be advanced at all. hydrateState() sweeps stale marks and
   backfills missing fields; it does not check the chain. */
test("AUDIT H7: a dot with no task behind it must not strand the scan", async () => {
  const stored = syncState({
    tasks: [syncTask("a", "Task A"), syncTask("b", "Task B")],
    chain: ["ghost"],                    // a hand-edited import, or a payload from another build
    updatedAt: Date.now(),
  });
  const { ctx } = await loadApp({
    seed: 8007,
    seedStorage: { [SYNC_STORE_KEY]: JSON.stringify(stored) },
  });

  assert.deepEqual(
    ctx.state.chain.filter((id) => !ctx.state.tasks.some((t) => t.id === id)), [],
    "every dot must point at a task that still exists");
  assert.ok(!(ctx.state.candidateId && !ctx.benchmark()),
    "a candidate must never be dealt with no benchmark for Yes/No to compare it against");
});

/* ---- H8: junk settings are type-checked on the way in, never range-checked ----
   normalizeSettings() exists so a settings object from an older device or a
   hand-edited import cannot turn the scan's arithmetic into NaN. It rejects
   non-numbers, then accepts any finite number at all — including ones the
   Settings form itself refuses. samples drives a Monte-Carlo run on every
   recomputeRanks(); a negative horizon puts the question's deadline in the
   past; thresholdPct above 90 interrupts on every single decision. */
test("AUDIT H8: hydrateState must reject settings the Settings form itself would refuse", async () => {
  const { ctx } = await loadApp({ seed: 8008 });
  const st = {
    v: 2, tasks: [], contexts: [], chain: [], considered: {}, cantAt: {}, workedAt: {}, workLog: [],
    settings: { horizonMin: -30, thresholdPct: 900, samples: 5000000, cantMin: 0, workedHours: -1, theme: "system" },
  };
  ctx.hydrateState(st);
  const s = st.settings;
  // Bounds are the min/max the Settings inputs already enforce.
  assert.ok(s.horizonMin >= 5 && s.horizonMin <= 480, `horizon out of range: ${s.horizonMin}`);
  assert.ok(s.cantMin >= 5 && s.cantMin <= 480, `can't window out of range: ${s.cantMin}`);
  assert.ok(s.workedHours >= 1 && s.workedHours <= 720, `worked window out of range: ${s.workedHours}`);
  assert.ok(s.thresholdPct >= 1 && s.thresholdPct <= 90, `threshold out of range: ${s.thresholdPct}`);
  assert.ok(s.samples >= 50 && s.samples <= 2000, `samples out of range: ${s.samples}`);
});

/* ---- H10: the worked-window label promises the opposite of what it does ----
   Settings says the window holds "at least this long — and never back the same
   day". workedUntil() takes min(), so the configured hours are a CEILING the
   02:00 day line can cut short: a mark made just after midnight is released at
   02:00, hours early, on the same calendar day. The arithmetic is deliberate
   and documented at workedUntil(); the copy is what drifted away from it. */
test("AUDIT H10: the worked-window label must not promise a hold the day line cuts short", async () => {
  const { ctx } = await loadApp({ seed: 8010 });
  ctx.state.settings.workedHours = 16;
  const at = new Date(2026, 0, 15, 0, 30).getTime();      // marked worked at 00:30
  const until = ctx.workedUntil(at);

  assert.ok(until - at < 16 * HOUR,
    "the day line really does cut the configured window short, so 'at least' cannot be true");
  assert.equal(new Date(until).getDate(), new Date(at).getDate(),
    "...and really does release it on the same calendar day");

  const row = html.match(/stWorkedHrs[\s\S]{0,400}?<\/div>/);
  assert.ok(row, "the Settings row for the worked window exists");
  assert.doesNotMatch(row[0], /at least/, "the label must not promise a minimum it does not keep");
  assert.doesNotMatch(row[0], /never back the same day/, "nor that the task cannot return today");
});

/* ---- H11: a skip mark reaches innerHTML unescaped ----
   Every other user-supplied string on a list row goes through esc(). The mark
   itself does not: skippedLabel() falls through to `return consid` for
   anything it doesn't recognise, and renderList() concatenates that straight
   into innerHTML. state.considered only ever holds four known words from the
   app's own code — but it is also a plain object in the payload, so an
   imported export or a state from another build can carry anything at all. */
test("AUDIT H11: an unrecognised skip mark is escaped like every other string on the row", async () => {
  const { ctx } = await loadApp({ seed: 8011 });
  const t = ctx.addTask("Ordinary task", false);
  ctx.state.considered[t.id] = '<img src=x onerror="alert(1)">';
  ctx.state.listOpen = true;
  ctx.render();

  const body = ctx.document.getElementById("listBody").innerHTML;
  assert.ok(!body.includes("<img src=x"), `the mark reached innerHTML as live markup: ${body}`);
  assert.ok(body.includes("&lt;img"), "it should render as text, the way a title does");
});

/* ---- H12: clearing history leaves the marks of what it removed ----
   deleteTask() and reconcileHistory() both sweep the chain, considered, cantAt
   and workedAt when they drop a task, precisely so no dead id is left behind.
   clearCompleted() removes tasks too — every done one — and sweeps none of it. */
test("AUDIT H12: clearing history leaves no mark or dot behind for the tasks it removes", async () => {
  const { ctx } = await loadApp({ seed: 8012 });
  const gone = ctx.addTask("Finished, and marked", false);
  ctx.addTask("Still open", false);
  // A done task carrying leftovers, which is what an older payload or a
  // hand-edited import hands us — completeTask() clears its own mark, so
  // nothing the app does today produces this on its own.
  // taskById is a top-level const arrow, so it never attaches to the sandbox
  // (same as esc) — reach the task through state instead.
  const t = ctx.state.tasks.find((x) => x.id === gone.id);
  t.done = true; t.completedAt = Date.now();
  ctx.state.considered[gone.id] = "no";
  ctx.state.cantAt[gone.id] = Date.now();
  ctx.state.workedAt[gone.id] = Date.now();
  ctx.state.chain.push(gone.id);

  ctx.clearCompleted();                       // confirm() is stubbed true

  assert.ok(!ctx.state.tasks.some((x) => x.id === gone.id), "the task is gone");
  assert.ok(!ctx.state.chain.includes(gone.id), "and so is its dot");
  assert.ok(!(gone.id in ctx.state.considered), "and its mark");
  assert.ok(!(gone.id in ctx.state.cantAt), "and its can't timestamp");
  assert.ok(!(gone.id in ctx.state.workedAt), "and its worked timestamp");
});

/* ---- H13: an adopted remote only reaches disk on one of the two backends ----
   cloudPull() writes the state it adopts straight to localStorage, bypassing
   persist() — so on the artifact host, where loadState() uses window.storage
   instead and useLocal is false, the adoption never reaches disk at all and a
   reload resurrects exactly what was just replaced. */
test("AUDIT H13: a remote adoption reaches disk on the artifact host too, not just localStorage", async () => {
  const now = Date.now();
  const h = makeSyncHarness({ remote: cloudState(now), rev: 4 });
  const local = staleState(now); local.syncRev = 3;
  const { ctx, shim } = await loadApp({
    seed: 8013,
    hostStorage: { [SYNC_STORE_KEY]: JSON.stringify(local) },
    cloudSyncFactory: h.factory,
  });
  assert.deepEqual(Array.from(ctx.state.chain), STALE_CHAIN, "booted from the host store, not localStorage");

  await ctx.cloudPull();
  assert.deepEqual(Array.from(ctx.state.chain), CLOUD_CHAIN, "the newer revision is adopted in memory");

  await flush();
  const onDisk = JSON.parse(shim.window.storage._map.get(SYNC_STORE_KEY));
  assert.deepEqual(onDisk.chain, CLOUD_CHAIN,
    "a reload must not resurrect the copy the adoption just replaced");
});

test('Landscape browser: every visitor renders with finite geometry across short and narrow views', {skip:!process.env.LANDSCAPE_BROWSER_URL}, async()=>{
  const {chromium}=await import(process.env.LANDSCAPE_PLAYWRIGHT);
  const browser=await chromium.launch({headless:true,channel:'chrome'});
  try{
    for(const spec of [{width:844,height:390},{width:320,height:568},{width:844,height:390,night:true}]){
      const viewport={width:spec.width,height:spec.height};
      const page=await browser.newPage({viewport});
      await page.clock.setFixedTime(new Date(spec.night?'2026-09-12T03:00:00Z':'2026-06-21T17:00:00Z')); const errors=[];page.on('pageerror',e=>errors.push(e.message));
      await page.addInitScript(()=>{
        localStorage.setItem('fvp:chain-scanner:landscape-motion','normal');
        window.invalidGeometry=[];
        for(const key of ['moveTo','lineTo','translate','rotate','ellipse','fillRect','bezierCurveTo']){
          const original=CanvasRenderingContext2D.prototype[key];
          CanvasRenderingContext2D.prototype[key]=function(...args){if(args.some(x=>typeof x==='number'&&!Number.isFinite(x)))invalidGeometry.push(key);return original.apply(this,args);};
        }
      });
      await page.route('**/landscape.js',async route=>{
        const response=await route.fetch();let body=await response.text();
        body=body.replace('let skyTimer=0',`world.events=[...LivingSky.eventTypes,...LivingSky.rareTypes,...LivingSky.nightEventTypes].map((type,i)=>({type,age:45,duration:100,seed:(i*.137)%1,lane:(i*.17)%1,reverse:i%2===0}));world.next=1e9;let skyTimer=0`);
        await route.fulfill({response,body});
      });
      await page.goto(process.env.LANDSCAPE_BROWSER_URL,{waitUntil:'networkidle'});
      await page.locator('#modalRoot [data-act="close-modal"]').click();
      const pane=await page.locator('.scene-reading').boundingBox();
      assert.ok(pane.width<viewport.width-32,'intro leaves the scene visible alongside it');
      await page.locator('#viewScene').click();await page.waitForTimeout(750);
      assert.equal(await page.locator('.wrap').evaluate(e=>getComputedStyle(e).opacity),'0');
      const coverage=await page.locator('[data-scenery]').evaluate(c=>{const g=c.getContext('2d');return [g.getImageData(0,c.height-1,1,1).data[3],g.getImageData(c.width-1,c.height-1,1,1).data[3]]});
      assert.deepEqual(coverage,[255,255]);
      assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);
      assert.deepEqual(await page.evaluate(()=>invalidGeometry),[]);
      await page.locator('#exitScene').click();await page.waitForTimeout(750);
      assert.equal(await page.locator('.wrap').evaluate(e=>getComputedStyle(e).opacity),'1');
      assert.deepEqual(errors,[]);await page.close();
    }
  }finally{await browser.close();}
});

 test('Landscape mood: seasons, clock hands and a time-specific message catalog work offline',()=>{
 const context=vm.createContext({Date,Intl,Math,JSON});
 vm.runInContext(fs.readFileSync(path.join(__dirname,'landscape-config.js'),'utf8'),context);vm.runInContext(fs.readFileSync(path.join(__dirname,'vendor/astronomy.min.js'),'utf8'),context);vm.runInContext(fs.readFileSync(path.join(__dirname,'landscape-mood.js'),'utf8'),context);
 const mood=context.LandscapeMood;const hexLuminance=landscapeLuminance;
  const date = value => new Date(value);

  assert.equal(mood.season(date('2026-03-20T16:00:00Z'), 28.5, 'America/New_York').name, 'spring');
  assert.equal(mood.season(date('2026-06-21T16:00:00Z'), 28.5, 'America/New_York').name, 'summer');
  assert.equal(mood.season(date('2026-12-21T22:00:00Z'), -33.9, 'Australia/Sydney').name, 'summer');
  const blend = mood.season(date('2026-06-16T16:00:00Z'), 28.5, 'America/New_York');
  assert.ok(blend.weights.spring >= 0 && blend.weights.spring < 1);
  assert.ok(Math.abs(Object.values(blend.weights).reduce((sum, value) => sum + value, 0) - 1) < 1e-8);

  const clock = mood.clock(date('2026-06-21T17:30:45.500Z'), 'America/New_York');
  assert.ok(Math.abs(clock.hourAngle - (Math.PI * (1.512638888888889 / 6))) < 1e-10);
  assert.ok(Math.abs(clock.minuteAngle - (Math.PI * (30.758333333333332 / 30))) < 1e-10);
  assert.throws(() => mood.clock(date('invalid'), 'America/New_York'), /date/i);

  const base = {
    sky: ['#8ed4f3', '#d4f5f2', '#f6fbe2'],
    city: '#bbdce1', far: '#c5e8b7', hill: '#ace097', front: '#8dcca1', tint: '#ade1c6', night: 0,
  };
  const toned = mood.palette(base, date('2026-10-05T16:00:00Z'), { latitude: 28.5, timezone: 'America/New_York' });
  assert.notStrictEqual(toned, base);
  assert.deepEqual(base.sky, ['#8ed4f3', '#d4f5f2', '#f6fbe2']);
  assert.notDeepEqual(toned.sky, base.sky, 'season should tint scenery');
  for (const color of [...toned.sky, toned.city, toned.far, toned.hill, toned.front, toned.tint]) {
    assert.match(color, /^#[0-9a-f]{6}$/);
  }
  assert.ok(hexLuminance(toned.front) > hexLuminance(base.front) * 0.75, 'tint keeps foreground luminous');

  const periods = [
    ['2026-06-21T08:00:00Z', 'predawn'], ['2026-06-21T13:00:00Z', 'morning'],
    ['2026-06-21T16:30:00Z', 'noon'], ['2026-06-21T20:00:00Z', 'afternoon'],
    ['2026-06-21T22:30:00Z', 'golden'], ['2026-06-22T00:30:00Z', 'evening'],
    ['2026-06-22T05:00:00Z', 'night'],
  ];
  const values = periods.map(([instant]) => mood.message(date(instant), { latitude: 28.5, timezone: 'America/New_York' }, () => 0));
  assert.ok(values.every(value => value === ''), 'no AI hourly fallback');
  assert.ok(mood.messageCount >= 100, 'catalog has a hundred curated combinations');
  assert.equal(mood.messages(date('2026-06-21T13:00:00Z'), { timezone: 'America/New_York' }, () => 0), values[1]);
  assert.equal(mood.message(date('2026-06-21T13:00:00Z'), { timezone: 'America/New_York' }, () => 0), mood.message(date('2026-06-21T13:00:00Z'), { timezone: 'America/New_York' }, () => 0));
  assert.equal(mood.message(date('2026-06-20T13:00:00Z'), { timezone: 'America/New_York' }, () => 0), mood.message(date('2026-12-21T14:00:00Z'), { timezone: 'America/New_York' }, () => 0));
  assert.equal(mood.period(date('2026-12-21T22:00:00Z'), { timezone: 'America/New_York', sunAltitude: -2 }), 'evening');
  assert.equal(mood.period(date('2026-12-21T22:00:00Z'), { timezone: 'America/New_York', sunAltitude: 4 }), 'golden-hour');
  assert.equal(mood.period(date('2026-12-21T22:00:00Z'), { timezone: 'America/New_York', sunAltitude: null }), 'golden-hour');
});

