test('RISK landscape shadows: each object projects away from the visible Sun or Moon position',()=>{
 const ctx=vm.createContext({Math});vm.runInContext(fs.readFileSync(path.join(__dirname,'landscape-geometry.js'),'utf8'),ctx);
 for(const [w,h] of [[390,844],[588,1280],[820,390]]){
  const g=ctx.LandscapeGeometry.create(w,h);
  const moon={sun:{altitude:-25,azimuth:90},moon:{altitude:35,azimuth:270,visible:true},illumination:1};
  const light=g.skyPoint(270,35),left=g.castShadow(moon,45,12,w*.55,h*.75),right=g.castShadow(moon,45,12,w*.95,h*.75);
  assert.equal(left.source,'moon');assert.equal(left.origin.x,light.x);assert.equal(left.origin.y,light.y);
  assert.ok(left.dx<0&&right.dx>0,'objects on opposite sides cast away from the painted Moon');
  assert.ok(left.dy>0&&right.dy>0,'the Moon above the skyline casts toward the foreground');
  const sun={sun:{altitude:22,azimuth:90,visible:true},moon:{altitude:35,azimuth:270,visible:true},illumination:1};
  const west=g.castShadow(sun,45,12,w*.1,h*.75),east=g.castShadow(sun,45,12,w*.5,h*.75);
  assert.equal(west.source,'sun');assert.ok(west.dx<0&&east.dx>0,'daylight follows the painted Sun on both sides');
  assert.equal(g.castShadow({...sun,sun:{altitude:1,azimuth:90},moon:{altitude:75,azimuth:270}},45,12,w*.5,h*.75).source,'sun',
   'even a low visible Sun dominates a high full Moon');
  const seam={...moon,moon:{altitude:35,azimuth:355,visible:true}};
  assert.ok(g.castShadow(seam,45,12,w*.03,h*.75).dx<0,'even at the screen edge, the visible Moon remains the light origin');
  const stars=g.castShadow({sun:{altitude:-25},moon:{altitude:-15},illumination:0},45,12,w*.5,h*.75);
  assert.equal(stars.source,'stars');assert.equal(stars.dx,0);assert.equal(stars.dy,0);
 }
 const source=fs.readFileSync(path.join(__dirname,'landscape.js'),'utf8');
 assert.match(source,/const point=\(az,alt\)=>geometry\.skyPoint\(az,alt\)/,'the Sun and Moon use the same projected point as the shadow source');
 assert.match(source,/geometry\.castShadow\(sky,height,width,x,y\)/,'grounded objects pass their own contact point');
 assert.match(source,/function paintRailShadow\(/,'rail shadows vary by track segment relative to the light');
});

test('RISK landscape shadows: high Sun draws short near-base shade on phone and landscape screens',()=>{
 const ctx=vm.createContext({Math});vm.runInContext(fs.readFileSync(path.join(__dirname,'landscape-geometry.js'),'utf8'),ctx);
 for(const [w,h] of [[390,844],[588,1280],[568,320]]){
  const geometry=ctx.LandscapeGeometry.create(w,h),x=w*.72,y=h*.76;
  const shade=altitude=>geometry.castShadow({sun:{altitude,azimuth:90,visible:true},moon:{altitude:-20},illumination:0},45,12,x,y);
  const low=shade(12),climbing=shade(30),autumnNoon=shade(40),high=shade(70),overhead=shade(85);
  const reach=s=>Math.hypot(s.dx,s.dy)+s.rx;
  assert.ok(reach(low)>=reach(climbing)&&reach(climbing)>reach(autumnNoon)&&reach(autumnNoon)>reach(high)&&reach(high)>=reach(overhead),`${w}x${h}: shadow contracts as Sun rises`);
  assert.ok(Math.hypot(autumnNoon.dx,autumnNoon.dy)<6&&autumnNoon.rx<9,`${w}x${h}: a modest autumn noon Sun already pools shade near the trunk`);
  assert.ok(Math.hypot(high.dx,high.dy)<5&&high.rx<8&&high.ry<4,`${w}x${h}: high Sun leaves a compact puddle near the trunk`);
  assert.ok(high.dx>0&&high.dy>0&&overhead.dx>0&&overhead.dy>0,`${w}x${h}: even short shade points away from the visible Sun`);
  const nearZenithMoon=geometry.castShadow({sun:{altitude:-20},moon:{altitude:89,azimuth:90,visible:true},illumination:1},45,12,x,y);
  assert.ok(Math.hypot(nearZenithMoon.dx,nearZenithMoon.dy)<1,`${w}x${h}: high Moon shade keeps its former length`);
 }
});

test('RISK landscape grass: visible far, middle, and near ground keep depth-scaled detail density',()=>{
 const ctx=vm.createContext({Math});vm.runInContext(fs.readFileSync(path.join(__dirname,'landscape-geometry.js'),'utf8'),ctx);
 for(const [W,H] of [[390,844],[568,320],[820,1180]]){
  const geometry=ctx.LandscapeGeometry.create(W,H),bands=['far','middle','near'].map(kind=>geometry.grassBand(kind));
  assert.ok(bands.every(band=>band.length>0),'every visible ground band receives grass');
  const avgHeight=band=>band.reduce((sum,blade)=>sum+blade.height,0)/band.length;
  assert.ok(avgHeight(bands[0])<avgHeight(bands[1])&&avgHeight(bands[1])<avgHeight(bands[2]),'grass gets smaller with distance');
  for(const [index,kind] of ['far','middle','near'].entries()){
   const band=bands[index],bounds=x=>kind==='far'?[geometry.far(x)+3,geometry.rail(x)-4]:kind==='middle'?[geometry.middle(x)+3,geometry.near(x)-12]:[geometry.near(x)+30,H-3];
   for(const blade of band){const [top,bottom]=bounds(blade.x);assert.ok(blade.y>=top&&blade.y<=bottom,`${kind} grass stays on its ground`);}
  }
  const density=(band,kind)=>{let depth=0;for(let i=0;i<9;i++){const x=W*i/8;depth+=kind==='far'?Math.max(0,geometry.rail(x)-4-(geometry.far(x)+3)):kind==='middle'?Math.max(0,geometry.near(x)-12-(geometry.middle(x)+3)):Math.max(0,H-3-(geometry.near(x)+30));}return band.length/(W*depth/9);};
  const farDensity=density(bands[0],'far'),midDensity=density(bands[1],'middle'),nearDensity=density(bands[2],'near');
  assert.ok(farDensity>nearDensity*.45&&farDensity<nearDensity*1.1,'far grass density is scaled to its narrow visible band');
  assert.ok(midDensity>nearDensity*.45&&midDensity<nearDensity*1.1,'middle grass density is comparable per visible area');
 }
 const source=fs.readFileSync(path.join(__dirname,'landscape.js'),'utf8');
 assert.match(source,/geometry\.grassBand\(kind\)/,'the grass painter uses the geometry bands');
 for(const kind of ['far','middle','near'])assert.match(source,new RegExp(`paintGrass\\('${kind}'`),`${kind} grass is painted`);
});

