 const cyclic=JSON.parse(JSON.stringify(ctx.state));ctx.hydrateState(cyclic);
 assert.equal(cyclic.tasks.find(t=>t.id===c.id).prerequisiteId,a.id,'reload must not silently break a saved cycle');
