test('RISK landscape water browser: GPU distortion preserves contact and sharp pixels while patches move independently',{skip:!process.env.LANDSCAPE_PLAYWRIGHT},async()=>{
 const {chromium}=await import(process.env.LANDSCAPE_PLAYWRIGHT),browser=await chromium.launch({channel:'chrome'});
 const runtime=fs.readFileSync(path.join(__dirname,'landscape.js'),'utf8');
 const helper=runtime.slice(runtime.indexOf('  function createWaterDistortion(){'),runtime.indexOf('  const waterDistortion='));
 try{
  const page=await browser.newPage();
  const result=await page.evaluate(helper=>{
   const factory=new Function(helper+';return createWaterDistortion;')(),renderer=factory();
   const source=document.createElement('canvas');source.width=390;source.height=300;
   const c=source.getContext('2d'),pixels=c.createImageData(390,300);
   for(let y=0;y<300;y++)for(let x=0;x<390;x++){
    const i=(y*390+x)*4;pixels.data[i]=x%16<8?240:20;pixels.data[i+1]=y%14<7?200:40;pixels.data[i+2]=y<150?70:150;pixels.data[i+3]=255;
   }
   c.putImageData(pixels,0,0);
   const copy=document.createElement('canvas');copy.width=390;copy.height=300;const ctx=copy.getContext('2d');
   const frame=t=>{const out=renderer.render(source,t,1,false,390,300);ctx.clearRect(0,0,390,300);ctx.drawImage(out,0,0);return {gpu:out!==source,data:ctx.getImageData(0,0,390,300).data};};
   const a=frame(0),b=frame(1.5);let changed=0,contactError=0,alphaMin=255,redTravel=0,greenTravel=0;
   for(let y=0;y<300;y++)for(let x=0;x<390;x++){
    const i=(y*390+x)*4;alphaMin=Math.min(alphaMin,b.data[i+3]);
    if(a.data[i]!==b.data[i])changed++;
    redTravel+=Math.abs(a.data[i]-b.data[i]);greenTravel+=Math.abs(a.data[i+1]-b.data[i+1]);
    if(y===299)for(let channel=0;channel<3;channel++)contactError=Math.max(contactError,Math.abs(b.data[i+channel]-pixels.data[i+channel]));
   }
   // At a horizontal stripe edge, neighboring patches receive different
   // vertical displacement, while the rigid vertical bars hardly snake.
   const verticalPatches=[32,96,160,224,288,352].map(x=>b.data[(251*390+x)*4+1]);
   const frozen=renderer.render(source,6,1,true,390,300)===source;
   const orientation=b.data[(20*390+5)*4+2]===70&&b.data[(280*390+5)*4+2]===150;
   source.width=568;source.height=132;c.fillStyle='#aabbcc';c.fillRect(0,0,568,132);
   const resized=renderer.render(source,2,1,false,568,132);
   return {gpu:a.gpu&&b.gpu,changed,contactError,alphaMin,redTravel,greenTravel,verticalPatches,frozen,orientation,resized:[resized.width,resized.height]};
  },helper);
  assert.equal(result.gpu,true,'real shader compiled and rendered');
  assert.ok(result.changed>10000,'substantial reflected detail animates');
  assert.ok(result.greenTravel>result.redTravel*1.8,'vertical shimmer dominates sideways edge travel');
  assert.ok(new Set(result.verticalPatches).size>=3,'same-depth patches compress horizontal detail differently');
  assert.ok(result.contactError<=1,'horizon contact row stays sharp and stationary');
  assert.equal(result.alphaMin,255,'no transparent seams or edge holes');
  assert.equal(result.orientation,true,'GPU upload preserves top and bottom');
  assert.equal(result.frozen,true);assert.deepEqual(result.resized,[568,132]);
 }finally{await browser.close();}
});

test('RISK CLOUD RECOVERY: a durable ordinary save retries and clears its stale cloud error without reload',async()=>{
 const storage=sharedScannerStorage(),{ctx,shim}=await loadApp({sharedStorage:storage});
 const cloud=recoveringCloudStatusHarness(shim,ctx);
 await ctx.cloudPull();
 cloud.fail('reconcile','invalid-payload');
 const set=storage.setItem;
 storage.setItem=(key,value)=>{
  if(key===LOCAL_HEAD_KEY||key===SYNC_STORE_KEY){const error=Error('site quota');error.name='QuotaExceededError';throw error;}
  set(key,value);
 };
 ctx.state.tasks.push(syncTask('recovered-edit','Edit that outlived device quota'));ctx.state.syncDirty=true;
 assert.equal(await ctx.persist(),false,'the production pair write records the local failure first');
 storage.setItem=set;
 assert.equal(await ctx.persist(),true,'automatic archive recovery makes the same board durable');
 await syncSettle(30);
 assert.equal(cloud.pulls(),2,'the successful local recovery retries the failed reconciliation automatically');
 assert.equal(cloud.CS.errorStage,null);assert.equal(cloud.CS.errorCode,null);
 assert.equal(shim.document.getElementById('syncBtn').textContent,'☁ syncing',
  'a successful read clears the stale error but cannot call an unacknowledged edit synced');
 assert.match(shim.document.getElementById('syncBtn').title,/pending|acknowledged|syncing/i,
  'the accessible status must not claim a pending board is already synced');
 ctx.cloudPushNow();await syncSettle(30);
 assert.equal(cloud.pushes(),1);assert.equal(cloud.remote().tasks.some(task=>task.id==='recovered-edit'),true);
 assert.equal(shim.document.getElementById('syncBtn').textContent,'☁ synced','the write acknowledgement completes recovery');
});

test('RISK CLOUD RECOVERY: Undo retries a failed write, while a failed retry and an account change stay errors', async()=>{
 const storage=sharedScannerStorage(),{ctx,shim}=await loadApp({sharedStorage:storage});
 // The recovery preflight can outlast 40ms on a slower host. Hold the third
 // backend acknowledgement so that elapsed time cannot masquerade as a write.
 let releaseRetry,acknowledgeRetry;
 const retryGate=new Promise(resolve=>{releaseRetry=resolve;});
 const retryAcknowledged=new Promise(resolve=>{acknowledgeRetry=resolve;});
 const cloud=recoveringCloudStatusHarness(shim,ctx,{beforePushAck:attempt=>attempt===3?retryGate:null});
 const push=cloud.CS.push;
 cloud.CS.push=async(...args)=>{
  const attempt=cloud.pushes()+1,result=await push(...args);
  if(attempt===3)acknowledgeRetry(result);
  return result;
 };
 await ctx.cloudPull();
 const task=ctx.addTask('Before Undo');await ctx.persist();ctx.cloudPushNow();await syncSettle(30);
 ctx.openEdit(task.id);fillEditPane(ctx,shim,{title:'After edit'});ctx.onAction('save-edit',{dataset:{id:task.id}});
 await ctx.persist();ctx.cloudPushNow();await syncSettle(30);
 cloud.fail('push','unavailable');
 const set=storage.setItem;let blocked=true;
 storage.setItem=(key,value)=>{
  if(blocked&&(key===LOCAL_HEAD_KEY||key===SYNC_STORE_KEY)){const error=Error('site quota');error.name='QuotaExceededError';throw error;}
  set(key,value);
 };
 ctx.undo();const undoFacts=JSON.stringify(ctx.state.decisionEvents);assert.equal(await ctx.persist(),false);
 blocked=false;assert.equal(await ctx.persist(),true);await syncSettle(40);
 assert.equal(cloud.pushes(),3,'durable recovery starts the automatic retry without waiting for the ordinary save debounce');
 assert.equal(ctx.state.tasks.find(row=>row.id===task.id).title,'Before Undo');
 assert.equal(JSON.parse(storage.getItem(LOCAL_HEAD_KEY)).tasks.find(row=>row.id===task.id).title,'Before Undo',
  'the exact Undo is durable before its cloud acknowledgement');
 assert.equal(JSON.stringify(JSON.parse(storage.getItem(LOCAL_HEAD_KEY)).decisionEvents),undoFacts,'the pending durable copy retains the exact edit and Undo facts');
 assert.equal(cloud.remote().tasks.find(row=>row.id===task.id).title,'After edit','an unacknowledged retry cannot already change the remote');
 assert.equal(ctx.state.syncDirty,true);assert.equal(shim.document.getElementById('syncBtn').textContent,'☁ syncing');
 releaseRetry();assert.equal((await retryAcknowledged).ok,true);await flush();
 assert.equal(cloud.remote().tasks.find(row=>row.id===task.id).title,'Before Undo');
 assert.equal(JSON.stringify(cloud.remote().decisionEvents),undoFacts,'the acknowledgement retains the exact edit and targeted Undo facts');
 assert.equal(cloud.CS.status,'ok');assert.equal(cloud.CS.errorStage,null);

 const failed=await loadApp({sharedStorage:sharedScannerStorage()});
 const stillBad=recoveringCloudStatusHarness(failed.shim,failed.ctx,{failedRetry:true});
 stillBad.fail('pull','unavailable');
 vm.runInContext("lastDeviceSaveIssue={stage:'primary-write',code:'quota-exhausted'}",failed.ctx);
 assert.equal(await failed.ctx.persist(),true);await syncSettle(30);
 assert.equal(stillBad.pulls(),1);assert.equal(stillBad.CS.status,'error');assert.equal(stillBad.CS.errorCode,'unavailable',
  'a failed automatic retry remains visibly failed');

 const switched=await loadApp({sharedStorage:sharedScannerStorage()});
 const stale=recoveringCloudStatusHarness(switched.shim,switched.ctx);
 stale.fail('reconcile','invalid-payload');
 vm.runInContext("lastDeviceSaveIssue={stage:'primary-write',code:'quota-exhausted'}",switched.ctx);
 const saved=switched.ctx.persist();stale.CS.user='other@example.test';await saved;await syncSettle(30);
 assert.equal(stale.pulls(),0,'a queued recovery from the old account cannot run under the new identity');
 assert.equal(stale.CS.status,'error','changing accounts does not let a stale callback clear the current error');
});

