test('RISK DEVICE STORAGE V2: raw export snapshot preserves exact sources in one read-only capture',async t=>{
 const {IDBFactory}=await import('fake-indexeddb'),indexedDB=new IDBFactory(),dbName='chain-scanner-raw-export-'+Date.now()+'-'+Math.random();
 const transactionReads=[];let openCalls=0,abortNextSnapshot=false;
 const nativeOpen=indexedDB.open.bind(indexedDB);
 indexedDB.open=(...args)=>{
  openCalls++;
  const request=nativeOpen(...args);
  request.addEventListener('success',event=>{
   const db=event.target.result,nativeTransaction=db.transaction.bind(db);
   db.transaction=(...transactionArgs)=>{
    const tx=nativeTransaction(...transactionArgs),names=Array.from(tx.objectStoreNames);
    transactionReads.push({names,mode:tx.mode});
    if(abortNextSnapshot&&tx.mode==='readonly'&&names.length===4){
     abortNextSnapshot=false;let issued=0;
     const nativeObjectStore=tx.objectStore.bind(tx);
     tx.objectStore=name=>{
      const objectStore=nativeObjectStore(name);
      for(const method of ['getAllKeys','getAll']){
       const nativeRequest=objectStore[method].bind(objectStore);
       objectStore[method]=(...requestArgs)=>{
        const result=nativeRequest(...requestArgs);
        if(++issued===8)tx.abort();
        return result;
       };
      }
      return objectStore;
     };
    }
    return tx;
   };
  });
  return request;
 };
 const storageV2=loadStorageV2({indexedDB}),store=storageV2.createDeviceStore({indexedDB,crypto:webcrypto,dbName});
 await store.open();t.after(async()=>{await store.close();});
 const rawOpen=await new Promise((resolve,reject)=>{
  const request=indexedDB.open(dbName);
  request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);
 });
 t.after(()=>rawOpen.close());
 const expected={
  meta:{keys:['head','pending:owner@example.test'],values:[
   {hash:'corrupt-head-hash',schemaVersion:99,futureMeta:{raw:new Uint8Array([0,255,128])}},
   {account:'owner@example.test',generationId:'pending-opaque-190',payloadHash:'not-a-hash',futurePending:{keep:['exact',7]}},
  ]},
  snapshots:{keys:['snapshot-corrupt'],values:[{hash:'mismatch',payload:new Uint8Array([123,0,255]),futureSnapshot:'keep'}]},
  backups:{keys:['manual-corrupt'],values:['raw\u0000backup\uD800bytes']},
  opaque:{keys:['opaque-archive'],values:[{raw:new Uint8Array([0,255,13]),futureOpaque:{retain:true}}]},
 };
 const seed=rawOpen.transaction(['meta','snapshots','backups','opaque'],'readwrite');
 for(const [name,fixture] of Object.entries(expected)){
  const objectStore=seed.objectStore(name);
  for(let index=0;index<fixture.keys.length;index++)objectStore.put(fixture.values[index],fixture.keys[index]);
 }
 await new Promise((resolve,reject)=>{seed.oncomplete=resolve;seed.onerror=()=>reject(seed.error);seed.onabort=()=>reject(seed.error||new Error('fixture seed aborted'));});
 const unopened=storageV2.createDeviceStore({indexedDB,crypto:webcrypto,dbName:dbName+'-unopened'}),opensBeforeUnopenedCall=openCalls;
 assert.equal(typeof store.readRawExportSnapshot,'function','the existing open device-store exposes the additive raw export port');
 await assert.rejects(unopened.readRawExportSnapshot(),/not open/i,'the export port cannot open or create a database on its own');
 assert.equal(openCalls,opensBeforeUnopenedCall,'reading from a closed handle performs no IndexedDB open');

 transactionReads.length=0;
 const readsBeforeSnapshot=openCalls,snapshot=await store.readRawExportSnapshot();
 assert.equal(openCalls,readsBeforeSnapshot,'a snapshot reuses the already-open database handle');
 assert.deepEqual(transactionReads,[{names:['backups','meta','opaque','snapshots'],mode:'readonly'}],
  'one readonly transaction covers all existing app-owned stores');
 assert.deepEqual(Object.keys(snapshot.stores).sort(),['backups','meta','opaque','snapshots']);
 for(const [name,fixture] of Object.entries(expected)){
  assert.deepEqual(Array.from(snapshot.stores[name].keys),fixture.keys,`${name} source keys remain exact`);
  assert.deepEqual(Array.from(snapshot.stores[name].values),fixture.values,`${name} raw values remain exact, including malformed and unknown rows`);
 }

 const unchanged=rawOpen.transaction(['meta','snapshots','backups','opaque'],'readonly');
 const unchangedRows=await Promise.all(Object.keys(expected).map(async name=>{
  const objectStore=unchanged.objectStore(name),[keys,values]=await Promise.all([
   new Promise((resolve,reject)=>{const request=objectStore.getAllKeys();request.onsuccess=()=>resolve(Array.from(request.result));request.onerror=()=>reject(request.error);}),
   new Promise((resolve,reject)=>{const request=objectStore.getAll();request.onsuccess=()=>resolve(Array.from(request.result));request.onerror=()=>reject(request.error);}),
  ]);
  return [name,{keys,values}];
 }));
 await new Promise((resolve,reject)=>{unchanged.oncomplete=resolve;unchanged.onerror=()=>reject(unchanged.error);unchanged.onabort=()=>reject(unchanged.error||new Error('verification read aborted'));});
 for(const [name,rows] of unchangedRows){
  assert.deepEqual(rows.keys,expected[name].keys,`${name} keys are unchanged after export`);
  assert.deepEqual(rows.values,expected[name].values,`${name} values are unchanged after export`);
 }

 transactionReads.length=0;abortNextSnapshot=true;
 await assert.rejects(store.readRawExportSnapshot(),/abort|transaction|request/i,'an aborted archive read rejects instead of producing a partial complete-looking snapshot');
 assert.equal(abortNextSnapshot,false,'the read reached the real four-store transaction');
 assert.deepEqual(transactionReads,[{names:['backups','meta','opaque','snapshots'],mode:'readonly'}]);
});

test('RISK SCALABLE BOARD CODEC: a multi-megabyte Unicode board roundtrips through bounded verified chunks',async()=>{
 const storageV2=loadStorageV2();
 const payload=JSON.stringify({tasks:Array.from({length:3200},(_,index)=>({
  id:'task-'+index,title:'Unicode '+index+' 😀 漢字 '+('\uD800')+' '+('recoverable '.repeat(32)),done:false,
 })),settings:{future:{unknown:true}}});
 assert.ok(Buffer.byteLength(payload,'utf8')>1048576,'fixture exceeds the old single-document ceiling');
 const encoded=await storageV2.encodeSnapshot(payload,{targetBytes:256*1024});
 assert.ok(encoded.chunks.length>4,'chunk count is data-driven rather than fixed to one document');
 assert.equal(encoded.chunkCount,encoded.chunks.length);
 assert.equal(encoded.byteLength,Buffer.byteLength(payload,'utf8'));
 for(const [index,chunk] of encoded.chunks.entries()){
  assert.equal(chunk.index,index);
  assert.ok(chunk.byteLength<=256*1024,'every Firestore chunk stays within the target');
  assert.equal(chunk.byteLength,Buffer.byteLength(chunk.text,'utf8'));
  assert.match(chunk.hash,/^[0-9a-f]{64}$/);
 }
 assert.equal(await storageV2.decodeSnapshot(encoded,encoded.chunks),payload,'UTF-8, emoji, escaped lone surrogates and unknown fields roundtrip byte-exactly');
 const tampered=encoded.chunks.map(row=>({...row}));tampered[1].text+='x';
 await assert.rejects(storageV2.decodeSnapshot(encoded,tampered),/hash|length|corrupt/i,'a damaged generation never becomes a board');
});

// #2239 round 2: a recovery reads the saved head many times, and each read
// fetched every saved snapshot (the head and each backup, each a whole board)
// to find the head's own. The head's snapshot is stored under its hash, so it
// is read by that key; a snapshot kept under any other key is still found by
// searching them all, in the same transaction, as before.
test('RISK DEVICE STORAGE V2: reading the saved head reads its own snapshot by key, and still finds one kept under another key',async t=>{
 const {indexedDB,IDBObjectStore}=await import('fake-indexeddb');
 const storageV2=loadStorageV2({indexedDB}),dbName='chain-scanner-head-read-'+Date.now()+'-'+Math.random();
 const store=storageV2.createDeviceStore({indexedDB,crypto:webcrypto,dbName});await store.open();t.after(()=>store.close());
 const board=label=>JSON.stringify({tasks:[{id:label,title:'Board '+label+' '+'x'.repeat(5000)}]});
 assert.equal((await store.migrateLegacy({headPayload:board('first'),backups:[{id:'daily-a',day:'2026-11-01',at:1,kind:'daily',payload:board('backup-a')},
  {id:'daily-b',day:'2026-11-02',at:2,kind:'daily',payload:board('backup-b')}]})).ok,true);
 const latest=board('latest'),prior=await store.readHead();
 assert.equal((await store.commitHead({expectedHash:prior.hash,payload:latest,account:null})).ok,true);
 // Count whole-store snapshot reads while the head is read.
 const getAll=IDBObjectStore.prototype.getAll;let snapshotScans=0;
 IDBObjectStore.prototype.getAll=function(...args){if(this.name==='snapshots')snapshotScans++;return getAll.apply(this,args);};
 t.after(()=>{IDBObjectStore.prototype.getAll=getAll;});
 const head=await store.readHead();
 IDBObjectStore.prototype.getAll=getAll;
 assert.equal(head.payload,latest,'the saved head reads back exactly');
 assert.equal(snapshotScans,0,'the head is read without reading every saved snapshot');
 // A head snapshot kept under another key (no writer stores one that way) is
 // still found, exactly, by the search over every snapshot.
 const moved=await new Promise((resolve,reject)=>{const request=indexedDB.open(dbName);request.onerror=()=>reject(request.error);request.onsuccess=()=>{
  const db=request.result,tx=db.transaction('snapshots','readwrite'),snapshots=tx.objectStore('snapshots');
  snapshots.delete(head.hash);snapshots.put({hash:head.hash,payload:latest},'moved-'+head.hash);
  tx.oncomplete=()=>{db.close();resolve(true);};tx.onerror=()=>reject(tx.error);};});
 assert.equal(moved,true);
 const found=await store.readHead();
 assert.equal(found.payload,latest,'a head snapshot under another key is still found');assert.equal(found.hash,head.hash);
});

test('RISK DEVICE STORAGE V2: migration and head plus recovery commits are atomic, CAS guarded, and preserve legacy bytes',async()=>{
 const {indexedDB}=await import('fake-indexeddb');
 const storageV2=loadStorageV2({indexedDB});
 const store=storageV2.createDeviceStore({indexedDB,crypto:webcrypto,dbName:'chain-scanner-test-'+Date.now()+'-'+Math.random()});
 await store.open();
 const legacyHead=JSON.stringify({tasks:[{id:'old',title:'Legacy 😀'}],future:{kept:true}});
 const unreadableArchive='opaque-old-shell-bytes:\u0000\uD800';
 const legacy={headPayload:legacyHead,sourceFingerprint:'legacy-pair-a',opaqueArchives:[{key:'daily-backups',raw:unreadableArchive}],
  backups:[{id:'manual-old',day:'2026-09-29',at:1,kind:'manual',payload:legacyHead}]};
 const before=structuredClone(legacy);
 const migrated=await store.migrateLegacy(legacy);
 assert.equal(migrated.ok,true);assert.equal(migrated.verified,true);
 assert.deepEqual(legacy,before,'migration never rewrites or deletes live legacy bytes');
 assert.equal((await store.readHead()).payload,legacyHead);
 assert.equal((await store.listBackups()).find(row=>row.id==='manual-old').payload,legacyHead);
 assert.deepEqual(await store.listOpaqueArchives(),legacy.opaqueArchives,'unreadable archives remain byte-exact recovery evidence');

 const next=JSON.stringify({tasks:[{id:'new',title:'Larger board '+('x'.repeat(20000))}],future:{kept:true}});
 const prior=await store.readHead();
 const committed=await store.commitHead({expectedHash:prior.hash,payload:next,account:'owner@example.test',
  backup:{id:'before-replace',day:'2026-09-29',at:2,kind:'before-cloud-local-edit',payload:legacyHead}});
 assert.equal(committed.ok,true);assert.equal((await store.readHead()).payload,next);
 assert.equal((await store.listBackups()).find(row=>row.id==='before-replace').payload,legacyHead,
  'the replacement head and its mandatory recovery copy commit together');

 const stale=await store.commitHead({expectedHash:prior.hash,payload:'{"tasks":[]}',account:'owner@example.test'});
 assert.equal(stale.conflict,true,'a tab cannot publish against a head it did not read');
 assert.equal((await store.readHead()).payload,next,'a failed CAS keeps the newer durable head');

 const collision=await store.commitHead({expectedHash:committed.hash,payload:'{"tasks":[{"id":"lost"}]}',account:'owner@example.test',
  backup:{id:'before-replace',day:'2026-09-29',at:3,kind:'manual',payload:'{"tasks":[{"id":"different"}]}'}});
 assert.equal(collision.error,true,'a conflicting recovery ID aborts rather than replacing old recovery data');
 assert.equal((await store.readHead()).payload,next,'the same transaction abort preserves the prior head');
 assert.equal((await store.listBackups()).find(row=>row.id==='before-replace').payload,legacyHead);
 await store.close();
});

// #2194 review L2 (characterization): the Settings decline releases the
// automatic recovery hold in the same transaction as the head. A tab holding
// an older hold must not release a different stored one or move the head.
test('RISK DEVICE STORAGE V2: a head commit releasing a recovery hold aborts on a different or missing stored hold and keeps head and hold exact',async()=>{
 const {indexedDB}=await import('fake-indexeddb');
 const storageV2=loadStorageV2({indexedDB});
 const store=storageV2.createDeviceStore({indexedDB,crypto:webcrypto,dbName:'chain-scanner-hold-release-'+Date.now()+'-'+Math.random()});
 await store.open();
 const recover=async(payload,hold)=>{const result=await store.writeRecoveredSource({expectedSource:'source',encodeSource:()=>'source',payload,account:'owner@example.test',hold});
  assert.equal(result.ok,true);return result;};
 const firstHold={reason:'cloud-source-recovery',automaticRecovery:true,account:'owner@example.test',identity:'owner',originalKey:'original-a'};
 await recover('{"tasks":[{"id":"recovered-a"}]}',firstHold);
 const staleHold=await store.getRecoveryCloudHold();
 assert.equal(staleHold.originalKey,'original-a','positive control: the first hold is stored');
 // A later recovery replaces the head and the hold (another tab, for example).
 await recover('{"tasks":[{"id":"recovered-b"}]}',{...firstHold,originalKey:'original-b'});
 const head=await store.readHead(),storedHold=await store.getRecoveryCloudHold();
 const declined='{"tasks":[{"id":"before-recovery"}]}';
 const mismatch=await store.commitHead({expectedHash:head.hash,payload:declined,account:'owner@example.test',releaseRecoveryHold:{expectedHold:staleHold}});
 assert.equal(mismatch.conflict,true,'a different stored hold aborts the commit as a conflict');
 assert.equal(mismatch.hash,head.hash,'the conflict reports the unchanged head');
 assert.deepEqual(await store.readHead(),head,'the head is unchanged');
 assert.deepEqual(await store.getRecoveryCloudHold(),storedHold,'the different stored hold is kept exactly');
 // Positive control: the exact stored hold is released with the head.
 const released=await store.commitHead({expectedHash:head.hash,payload:declined,account:'owner@example.test',releaseRecoveryHold:{expectedHold:storedHold}});
 assert.equal(released.ok,true,'the exact stored hold releases with the head');
 assert.equal((await store.readHead()).payload,declined);
 assert.equal(await store.getRecoveryCloudHold(),null,'the hold is deleted in the same commit');
 // With no stored hold left, asking to release one is also a conflict.
 const after=await store.readHead();
 const missing=await store.commitHead({expectedHash:after.hash,payload:'{"tasks":[]}',account:'owner@example.test',releaseRecoveryHold:{expectedHold:storedHold}});
 assert.equal(missing.conflict,true,'a missing stored hold aborts the commit');
 assert.deepEqual(await store.readHead(),after,'the head is unchanged when no hold is stored');
 await store.close();
});

test('RISK DEVICE STORAGE V2: unreferenced immutable snapshots retire while head and recovery references remain exact',async()=>{
 const {indexedDB}=await import('fake-indexeddb'),dbName='chain-scanner-gc-'+Date.now()+'-'+Math.random();
 const storageV2=loadStorageV2({indexedDB}),store=storageV2.createDeviceStore({indexedDB,crypto:webcrypto,dbName});
 await store.open();
 const first='{"tasks":[{"id":"first"}]}',second='{"tasks":[{"id":"second"}]}',third='{"tasks":[{"id":"third"}]}';
 await store.migrateLegacy({headPayload:first,backups:[],opaqueArchives:[]});
 let head=await store.readHead();
 let result=await store.commitHead({expectedHash:head.hash,payload:second,backup:{id:'kept-first',day:'2026-09-29',at:1,kind:'manual',payload:first}});
 result=await store.commitHead({expectedHash:result.hash,payload:third});
 const openDb=()=>new Promise((resolve,reject)=>{const request=indexedDB.open(dbName);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});
 const snapshotPayloads=async()=>{const db=await openDb();try{return await new Promise((resolve,reject)=>{const request=db.transaction('snapshots').objectStore('snapshots').getAll();request.onsuccess=()=>resolve(request.result.map(row=>row.payload));request.onerror=()=>reject(request.error);});}finally{db.close();}};
 assert.deepEqual(new Set(await snapshotPayloads()),new Set([first,third]),'the live head and referenced recovery remain, while an unreferenced intermediate head retires');
 assert.equal(await store.deleteBackup('kept-first',{payload:first,allowedKinds:['manual']}),true);
 assert.deepEqual(await snapshotPayloads(),[third],'deleting the last recovery reference retires its immutable payload but never the head');
 await store.close();
});

