test('RISK SCALABLE QUOTA: optional IndexedDB history cannot block a primary board that fits',async()=>{
 const {indexedDB}=await import('fake-indexeddb'),dbName='chain-scanner-idb-quota-'+Date.now()+'-'+Math.random();
 const initial=syncState({tasks:[syncTask('base','Base')]});
 const raw=JSON.stringify(initial),storage=sharedScannerStorage({[LOCAL_HEAD_KEY]:raw,[SYNC_STORE_KEY]:raw});
 // This legacy quota fallback has no expendable diagnostic allocation; the separate debug-log RISK covers the one permitted cleanup retry.
 const storageWrite=storage.setItem;storage.setItem=(key,value)=>{if(key==='fvp:chain-scanner:restart-diagnostics:v1')throw Object.assign(Error('diagnostics unavailable'),{name:'QuotaExceededError'});return storageWrite(key,value);};
 const {ctx,shim}=await loadApp({sharedStorage:storage,indexedDBProvider:indexedDB,deviceDbName:dbName});
 ctx.addTask('First durable edit');assert.equal(await ctx.persist(),true);
 const manual=await ctx.saveDurableBackup('manual',JSON.stringify(ctx.state));assert.ok(manual?.id);
 const before=await shim.window.ScannerDeviceStore.listBackups(),automatic=before.filter(row=>['daily','latest'].includes(row.kind));
 assert.ok(automatic.length>=1,'precondition: optional automatic history consumes device capacity');
 const store=shim.window.ScannerDeviceStore,original=store.commitHead.bind(store);let quotaFailures=0,retryOptions=null;
 store.commitHead=async options=>{
  if(options.backups?.length){quotaFailures++;throw Object.assign(Error('synthetic IndexedDB quota'),{name:'QuotaExceededError'});}
  retryOptions=options;return original(options);
 };
 ctx.addTask('Primary still fits');assert.equal(await ctx.persist(),true,'optional history quota falls back to the guarded primary write');
 const head=await store.readHead(),rows=await store.listBackups();
 assert.equal(JSON.parse(head.payload).tasks.some(row=>row.title==='Primary still fits'),true);
 assert.equal(quotaFailures,1);assert.ok(automatic.every(row=>retryOptions.removeBackupIds.includes(row.id)),'retry retires only eligible automatic references');
 assert.ok(rows.some(row=>row.id===manual.id&&row.kind==='manual'),'manual recovery remains byte-exact');
 assert.ok(rows.every(row=>!automatic.some(old=>old.id===row.id)),'retired automatic history no longer consumes snapshot references');
 await store.close();
});

test('RISK oldest never done: both modes prefer never-completed tasks and keep worked tasks eligible',async()=>{
 for(const mode of ['descending','chance']){
  const {ctx}=await loadApp();
  const recurring=ctx.addTask('Previously done'),worked=ctx.addTask('Worked only'),fresh=ctx.addTask('Fresh');
  recurring.createdAt=1;worked.createdAt=2;fresh.createdAt=3;
  recurring.evergreen=true;ctx.completeTask(recurring);recurring.lastDoneAt=1;
  ctx.workedOnTask(worked.id);ctx.state.considered={};ctx.state.workedAt={};
  ctx.startScan(mode);
  assert.equal(ctx.state.chain[0],worked.id,'Worked on it does not count as Done');
  assert.ok(ctx.pool().some(t=>t.id===recurring.id),'previously done tasks remain available for later comparison');
 }
});
test('RISK oldest never done: legacy completion and restore evidence survives reload and reconciliation',async()=>{
 for(const evidence of [{lastDoneAt:1},{completedAt:1},{restoredAt:1}]){
  const {ctx}=await loadApp();const old=ctx.addTask('Old'),fresh=ctx.addTask('Never done');
  old.createdAt=1;fresh.createdAt=2;Object.assign(old,evidence);
  const saved=JSON.parse(JSON.stringify(ctx.state));
  const reopened=await loadApp({seedStorage:{'fvp:chain-scanner:v1':JSON.stringify(saved)}});
  assert.equal(reopened.ctx.oldestFirst(reopened.ctx.pool()).id,fresh.id,'legacy evidence is honored after reload');
 }
 const {ctx}=await loadApp();const old=ctx.addTask('Restored'),fresh=ctx.addTask('Never done');
 old.createdAt=1;fresh.createdAt=2;ctx.doneTask(old.id);ctx.reopenTask(old);
 const stale=JSON.parse(JSON.stringify(ctx.state));delete stale.tasks[0].restoredAt;delete stale.tasks[0].restoredRunOp;
 ctx.mergeUndeletedTasks(stale,JSON.parse(JSON.stringify(ctx.state)));
 assert.equal(ctx.oldestFirst(stale.tasks).id,fresh.id,'reconciled restore remains completion evidence');
});
test('RISK oldest never done: all-completed fallback and eligibility boundaries preserve usable scans',async()=>{
 const {ctx}=await loadApp();const a=ctx.addTask('Old recurring'),b=ctx.addTask('New recurring'),held=ctx.addTask('Future never done');
 a.createdAt=1;b.createdAt=2;held.createdAt=0;held.startsAt='2099-01-01';
 a.lastDoneAt=1;b.lastDoneAt=2;
 assert.equal(ctx.oldestFirst(ctx.pool()).id,a.id,'all previously completed tasks still allow a scan');
 assert.equal(ctx.oldestFirst([]),null);
 delete b.lastDoneAt;
 assert.equal(ctx.oldestFirst(ctx.pool()).id,b.id,'an eligible never-done task takes precedence');
});

test('RISK CLOUD V2 STARTUP: transport and permission failures retain their code instead of masquerading as corrupt data',async()=>{
 for(const method of ['readGeneration','readChunks'])for(const code of ['unavailable','deadline-exceeded','permission-denied','unauthenticated']){
  const adapter=cloudV2Adapter(),store=loadCloudV2().createCloudStore({adapter,crypto:webcrypto});
  const payload=JSON.stringify({tasks:[{id:'kept'}]});await store.push('owner',payload,1,0);
  const original=adapter[method];adapter[method]=async()=>{throw Object.assign(Error('private transport detail'),{code:'firestore/'+code});};
  const failed=await store.pull('owner');assert.equal(failed.error,true);assert.equal(failed.code,code,'the read failure must retain its retry/authorization meaning');
  assert.equal(adapter.roots.get('owner').rev,1,'failed reads never write');
  adapter[method]=original;assert.equal((await store.pull('owner')).payload,payload,'the same intact generation remains readable');
 }
});
test('RISK CLOUD V2 STARTUP: a transient chunk read automatically recovers to synced without reloading the board',async()=>{
 const local=syncState({tasks:[syncTask('shared','Saved board')],syncRev:1,syncAccount:'e@example.com',syncDirty:false});
 const adapter=cloudV2Adapter(),store=loadCloudV2().createCloudStore({adapter,crypto:webcrypto});
 const payload=JSON.stringify(local);await store.push('owner',payload,1,0);
 const read=adapter.readChunks;let attempts=0,pushes=0;
 adapter.readChunks=async(...args)=>{if(++attempts===1)throw Object.assign(Error('temporary connection'),{code:'unavailable'});return read(...args);};
 const factory=window=>{
  const CS={configured:true,ready:true,user:'e@example.com',status:'ok',signIn(){},signOut(){},
   async pull(){const result=await store.pull('owner');CS.status=result.error?'error':'ok';CS.errorStage=result.error?'pull':null;CS.errorCode=result.code||null;window.dispatchEvent({type:'cloudsync'});return result;},
   async push(){pushes++;throw Error('no upload is needed');}};return CS;
 };
 const {ctx,shim}=await loadApp({seedStorage:{[SYNC_STORE_KEY]:payload},cloudSyncFactory:factory});
 shim.window.CLOUD_RETRY_DELAY_MS=5;await ctx.cloudPull();
 assert.equal(shim.document.getElementById('syncBtn').textContent,'☁ error');await syncSettle(80);
 assert.equal(attempts,2,'a transient chunk failure must enter the existing bounded retry path');
 assert.equal(shim.document.getElementById('syncBtn').textContent,'☁ synced');assert.equal(pushes,0);
 assert.equal(ctx.state.tasks[0].id,'shared');assert.equal(adapter.roots.get('owner').rev,1);
});

