test('RISK DESTRUCTIVE ACTION RACE: Restore and Reset stop if their backed-up board or account changes',async t=>{
 for(const action of ['restore','reset'])for(const change of ['board','account','backend'])await t.test(action+' / '+change,async()=>{
  const {ctx,shim}=await loadApp();
  ctx.addTask('Original account work');ctx.state.syncAccount='original@example.test';assert.equal(await ctx.persist(),true);
  const manual=await ctx.saveDurableBackup('manual',JSON.stringify(ctx.state));
  ctx.state.tasks[0].title='Current work';assert.equal(await ctx.persist(),true);
  shim.window.CloudSync={ready:false,user:'original@example.test',status:'ok'};
  const originalSave=ctx.saveDurableBackup;let release,started;
  const waiting=new Promise(resolve=>started=resolve);
  ctx.saveDurableBackup=async(...args)=>{const copy=await originalSave(...args);started();await new Promise(resolve=>release=resolve);return copy;};
  const before=JSON.stringify(ctx.state);
  const pending=action==='restore'?ctx.restoreDurableBackupById(manual.id):ctx.confirmResetEverything();
  await waiting;
  if(change==='board')ctx.addTask('New work while backup waits');
  if(change==='account')shim.window.CloudSync.user='different@example.test';
  if(change==='backend')shim.window.CloudSync={...shim.window.CloudSync};
  const expected=JSON.stringify(ctx.state),undo=vm.runInContext('JSON.stringify(undoStack)',ctx);
  release();await pending;
  assert.equal(JSON.stringify(ctx.state),expected,'a stale destructive action must not replace newer state');
  assert.equal(vm.runInContext('JSON.stringify(undoStack)',ctx),undo,'cancelled action cannot add Undo frames');
  assert.ok(ctx.readLocalBackups().some(row=>row.kind==='before-'+action&&row.payload===before),'the completed safety copy remains recoverable');
  assert.match(shim.document.getElementById('toast').textContent,/stopped.*changed/i);
  vm.runInContext('if(saveTimer)clearTimeout(saveTimer);if(cloudTimer)clearTimeout(cloudTimer)',ctx);
 });
});

// Night-show regressions cover clocks and pixels separately: a changing array
// alone does not prove a visible window or a firework reaches the lake.
test('RISK night shows: standalone fireworks recur independently of the rare cooldown and stay bounded',()=>{
 const sky=livingSky(),night={sun:{altitude:-20,azimuth:0}};
 const w=sky.createWorld(()=>0);w.events=[];w.next=Infinity;w.railNext={train:Infinity,metro:Infinity};
 w.nextFireworks=0;w.nextFestival=Infinity;w.lastRare=0;
 sky.advance(w,1,night);
 assert.equal(w.events.filter(e=>e.type==='fireworks').length,1,'standalone fireworks do not wait seven minutes');
 assert.equal(w.lastRare,0,'standalone shows do not delay the festival or alien visit');
 for(let i=0;i<70;i++)sky.advance(w,1,night);
 assert.equal(w.events.filter(e=>e.type==='fireworks').length,0,'the minimum-minute show finishes before its full rest');
 for(let i=0;i<410;i++)sky.advance(w,1,night);
 assert.equal(w.events.filter(e=>e.type==='fireworks').length,1,'a second independent show starts after its sampled duration and full rest');
 assert.ok(w.events.length<=sky.MAX_EVENTS);
 const day=sky.createWorld(()=>0);day.events=[];day.next=Infinity;day.railNext=w.railNext;day.nextFireworks=0;day.nextFestival=0;
 sky.advance(day,100,{sun:{altitude:8,azimuth:0}});
 assert.ok(day.events.every(e=>!['fireworks','festival'].includes(e.type)),'full daytime remains excluded for both show sources');
 const full=sky.createWorld(()=>0);full.events=Array.from({length:sky.MAX_EVENTS},()=>({type:'walker',age:0,duration:100}));full.nextFireworks=0;full.nextFestival=0;
 sky.advance(full,1,night);assert.equal(full.events.length,sky.MAX_EVENTS,'shows cannot bypass the scene budget');
});

test('RISK night shows: festival odds are lower than standalone fireworks with finite visits and rate controls',()=>{
 const ctx=vm.createContext({Date,Math,console});
 for(const file of ['landscape-config.js','vendor/astronomy.min.js','stars.js','landscape-core.js'])vm.runInContext(fs.readFileSync(path.join(__dirname,file),'utf8'),ctx);
  const sky=ctx.LivingSky;
  assert.ok(sky.rareTypes.includes('festival'));
  assert.equal(ctx.LandscapeConfig.nightShows.festival.chance,.012,'festival chance doubles the released six-tenths-percent check');
  assert.equal(ctx.LandscapeConfig.setSpawnRates('| Event | Rate |\n| festival | 0 |\n| fireworks | 0 |'),true);
 const run=(roll,altitude=-20)=>{
  const w=sky.createWorld(()=>roll);w.events=[];w.next=Infinity;w.railNext={train:Infinity,metro:Infinity};w.nextFireworks=0;w.nextFestival=0;
  sky.advance(w,1,{sun:{altitude,azimuth:0}});return w;
 };
 assert.equal(run(0).events.length,0,'zero rates disable both shows');
 ctx.LandscapeConfig.setSpawnRates('| Event | Rate |\n| festival | 1 |\n| fireworks | 1 |');
  assert.ok(run(.005).events.some(e=>e.type==='festival'),'a roll below the one-minute .012 chance enters');
  assert.ok(!run(.013).events.some(e=>e.type==='festival'),'rolls above the one-minute .012 chance wait');
  assert.ok(run(.3).events.some(e=>e.type==='fireworks'),'standalone shows have forty percent checks');
  const w=run(.005),festival=w.events.find(e=>e.type==='festival');
 assert.equal(festival.duration,150/sky.startingSpeed(.005));assert.equal(festival.speed,sky.startingSpeed(.005));
 w.nextFireworks=Infinity;w.nextFestival=Infinity;sky.advance(w,festival.duration+1,{sun:{altitude:-20,azimuth:0}});
 assert.ok(!w.events.some(e=>e.type==='festival'),'the final fade retires the event');
 assert.ok(run(0,20).events.length===0);
});

