 t.after(async()=>{
  try{CS.user=null;vm.runInContext('clearTimeout(saveTimer);saveTimer=null;clearTimeout(cloudTimer);cloudTimer=null;clearCloudRetry();',ctx);}catch{}
  try{store.commitHead=commit;await store.close();}catch{}
 });
