 const base=JSON.parse(JSON.stringify(ctx.state));const left=await loadApp({seedStorage:{[SYNC_STORE_KEY]:JSON.stringify(base)}}),right=await loadApp({seedStorage:{[SYNC_STORE_KEY]:JSON.stringify(base)}});
