// Specialist review, blocking: a finished cloud recovery keeps a
// decision-recovery-confirmed copy as its record. Later cloud saves read that
// record to know the incident is over; with it deleted, every save re-read the
// whole recovery archive. The copies a recovery keeps are its records and
// originals, so none of them is deleted in bulk.
test('RISK delete red backups: the records and originals a recovery keeps are not counted or deleted in bulk, however old',async()=>{
 const now=Date.parse('2026-10-06T12:00:00Z'),old=now-30*24*HOUR,storage=sharedScannerStorage();
 const {ctx,shim}=await loadApp({sharedStorage:storage});setFakeTime(ctx,now);
 const payload=JSON.stringify(ctx.state),row=(id,kind,i)=>({id,kind,day:'2026-09-06',at:old-i*HOUR,payload});
 const kept=['decision-recovery-confirmed','decision-recovery-superseded','decision-recovery-pending','decision-recovery-cloud','decision-recovery-device'].map((kind,i)=>row(kind,kind,i));
 const asked=[];ctx.confirm=message=>{asked.push(message);return true;};
 storage.setItem(LOCAL_BACKUPS_KEY,JSON.stringify(kept));ctx.openSettings();
 assert.equal(redBackupsButton(shim.document.getElementById('modalRoot').innerHTML),null,'recovery records alone offer no button');
 const rows=[kept[0],kept[1],row('mine','manual',9),kept[2],kept[3],kept[4]];
 storage.setItem(LOCAL_BACKUPS_KEY,JSON.stringify(rows));ctx.openSettings();
 assert.equal(redBackupsButton(shim.document.getElementById('modalRoot').innerHTML)?.[3],'Delete 1 backup older than seven days');
 await whileAlive(ctx.onAction('delete-old-backups',{}));
 assert.equal(asked.length,1);
 assert.equal(storage.getItem(LOCAL_BACKUPS_KEY),JSON.stringify(kept),'every recovery record and original keeps its exact bytes and order');
 assert.equal(shim.document.getElementById('toast').textContent,'Deleted 1 backup older than seven days from this device.');
});

// Coverage limit: each recovery state is set on the loaded app directly, not
// reached through a failing cloud or device read. Settings' own notice for the
// state is asserted so the fixture is the state Settings recognises.
test('RISK delete red backups: while a recovery is unsettled the button is unavailable with its reason, a forced press deletes nothing, and each row keeps its own Delete',async()=>{
 const now=Date.parse('2026-10-06T12:00:00Z'),old=now-30*24*HOUR;
 const states=[
  ['saved source needs recovery','liveBoardAccepted=false','liveBoardAccepted=true',/Saved device source needs recovery/],
  ['cloud recovery pending','deviceRecoveryCloudHold={workspace:"working-board",reason:"cloud-source-recovery"}','deviceRecoveryCloudHold=null',/Cloud recovery is pending/],
  ['cloud recovery waiting','window.CloudSync={configured:true,ready:true,user:"e@example.com",status:"synced"};automaticRecoveryWaiting={backend:window.CloudSync,account:"e@example.com",identity:cloudAccountIdentity()}','automaticRecoveryWaiting=null',/Cloud recovery is waiting/],
 ];
 for(const [name,enter,leave,notice] of states){
  const storage=sharedScannerStorage(),{ctx,shim}=await loadApp({sharedStorage:storage});setFakeTime(ctx,now);
  const payload=JSON.stringify(ctx.state),rows=['one','two'].map(id=>({id,kind:'manual',day:'2026-09-06',at:old,payload})),raw=JSON.stringify(rows);
  storage.setItem(LOCAL_BACKUPS_KEY,raw);
  const asked=[];ctx.confirm=message=>{asked.push(message);return true;};
  vm.runInContext(enter,ctx);ctx.openSettings();
  let markup=shim.document.getElementById('modalRoot').innerHTML;
  assert.match(markup,notice,name+': fixture shows Settings\' own recovery notice');
  const waiting=redBackupsButton(markup);
  assert.ok(waiting,name+': the button stays visible so the reason has something to explain');
  assert.match(waiting[2],/ disabled/,name+': the button is unavailable');
  assert.deepEqual(waiting[1].split(/\s+/),['btn','subtle'],name+': it takes the one button style that has a disabled look, not the red one that looks pressable');
  const reason=markup.match(/<p id="oldBackupsWait"[^>]*>([^<]*)<\/p>/);
  assert.ok(reason&&waiting[2].includes('aria-describedby="oldBackupsWait"'),name+': the reason is tied to the button');
  assert.match(reason[1],/waits until recovery settles/i);assert.match(reason[1],/each backup can still be deleted by itself/i);
  for(const id of ['one','two'])assert.doesNotMatch(markup.match(new RegExp('<button class="[^"]+" data-act="delete-local-backup" data-id="'+id+'"([^>]*)>'))[1],/disabled/,name+': the row keeps its own Delete');
  assert.equal(await whileAlive(ctx.onAction('delete-old-backups',{})),false,name+': a forced or stale press is refused');
  assert.equal(asked.length,0,name+': nothing is asked');
  assert.equal(storage.getItem(LOCAL_BACKUPS_KEY),raw,name+': every backup keeps its exact bytes');
  vm.runInContext(leave,ctx);ctx.openSettings();
  markup=shim.document.getElementById('modalRoot').innerHTML;
  assert.doesNotMatch(redBackupsButton(markup)[2],/disabled/,name+': the button returns once recovery has settled');
  assert.ok(redBackupsButton(markup)[1].split(/\s+/).includes('danger'),name+': and is red again');
  assert.doesNotMatch(markup,/id="oldBackupsWait"/);
 }
});

test('RISK fireworks occurrence: standalone sampled starts are exactly four times the original interval while duration odds budgets and festival timing stay intact',()=>{
 const load=(released=false)=>{const context=vm.createContext({Date,Math,console});for(const file of ['landscape-config.js','vendor/astronomy.min.js','stars.js','landscape-core.js']){let source=fs.readFileSync(path.join(__dirname,file),'utf8');if(released){const r=spawnSync('git',['show','d4ceaaa74f9494538d16044b968f8cfcfe75fb5b:'+file],{cwd:__dirname,encoding:'utf8'});assert.equal(r.status,0);source=r.stdout;}vm.runInContext(source,context);}return context;};
 for(const rate of [0,1,2,10]){
  const trace=context=>{let seed=97631;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/2**32;},sky=context.LivingSky;
   context.LandscapeConfig.setSpawnRates('| Event | Rate |\n| fireworks | '+rate+' |');
   const world=sky.createWorld(random);world.events=[];world.next=Infinity;world.nextFestival=Infinity;world.railNext={train:Infinity,metro:Infinity};
   const shows=[];for(let i=0;i<100&&shows.length<5;i++){sky.advance(world,world.nextFireworks-world.elapsed,{sun:{altitude:-20,azimuth:0}});const show=world.events.find(e=>e.type==='fireworks');if(show)shows.push({start:world.elapsed,duration:show.duration});assert.ok(world.events.length<=sky.MAX_EVENTS);}return shows;};
  const legacy=load(true),current=load(),before=trace(legacy),after=trace(current);
  assert.deepEqual(after.map(e=>e.duration),before.map(e=>Math.min(60,e.duration)),'the requested cap changes visible duration without changing start frequency');
  assert.deepEqual(after.map(e=>e.start),before.map(e=>e.start*4),'every same-sample start, including failed chances, is spaced by exactly four times the original schedule');
  assert.equal(current.LandscapeConfig.nightShows.fireworks.chance,legacy.LandscapeConfig.nightShows.fireworks.chance,'do not confuse opportunity frequency with conditional odds');
  assert.deepEqual(JSON.parse(JSON.stringify(current.LandscapeConfig.nightShows.festival)),{...JSON.parse(JSON.stringify(legacy.LandscapeConfig.nightShows.festival)),chance:.012},'the barge visit and rare-event cooldown stay intact');
  assert.equal(current.LivingSky.MAX_EVENTS,legacy.LivingSky.MAX_EVENTS);
 }
});

test('RISK fireworks density and finale: paired regular shells lead to eight visible finale shells within a fixed budget and natural fade',()=>{
 const load=(released=false)=>{const context=vm.createContext({Math});let source=fs.readFileSync(path.join(__dirname,'landscape-geometry.js'),'utf8');if(released){const r=spawnSync('git',['show','d4ceaaa74f9494538d16044b968f8cfcfe75fb5b:landscape-geometry.js'],{cwd:__dirname,encoding:'utf8'});assert.equal(r.status,0);source=r.stdout;}vm.runInContext(source,context);return context.LandscapeGeometry;};
 const previous=load(true),current=load();
 for(const [width,height] of [[320,568],[390,844],[568,320],[768,1024],[1440,900]])for(const festival of [false,true]){
  const old=previous.create(width,height),geometry=current.create(width,height),duration=festival?150:180,event={type:festival?'festival':'fireworks',duration,seed:.4};
  const shells=dots=>new Set(dots.map(dot=>dot.burst)).size;
  for(const age of festival?[41.6,45.4,49.2]:[1.6,21.6,41.6])assert.equal(shells(geometry.fireworks(age,.4,festival,event)),2*shells(old.fireworks(age,.4,festival,event)),`${width}x${height}/${festival?'barge':'standalone'}/${age}: twice the regular shells are airborne while both launchers are on screen`);
  const finaleAt=festival?Math.min(duration*.65,duration-3.775):Math.min(duration,60)-4,peak=geometry.fireworks(finaleAt+1.6,.4,festival,event);
  assert.equal(shells(peak.filter(dot=>dot.finale)),8,'the chosen eight-shell finale is visibly larger than a normal paired volley');
  assert.ok(peak.some(dot=>dot.kind==='spark'));
  const alpha=age=>geometry.fireworks(age,.4,festival,event).reduce((total,dot)=>total+dot.alpha,0);
  assert.ok(alpha(finaleAt+1.6)>alpha(finaleAt+2.6));assert.ok(alpha(finaleAt+2.6)>alpha(finaleAt+3.6));assert.equal(alpha(finaleAt+3.775),0,'remaining embers fully fade rather than cutting off at the event boundary');
  for(const age of [0,.4,1.6,21.6,finaleAt+.4,finaleAt+1.6,finaleAt+2.6,finaleAt+3.6,duration]){
   const dots=geometry.fireworks(age,.4,festival,event);assert.ok(dots.length<=320,'eight shells share the fixed 320-particle ceiling');
   assert.ok(dots.every(dot=>[dot.x,dot.y,dot.alpha].every(Number.isFinite)&&dot.alpha>0&&dot.alpha<=1));assert.ok(dots.every(dot=>dot.x>=(dot.finale?0:-128)&&dot.x<=width+(dot.finale?0:128)&&dot.y>=0&&dot.y<=geometry.waterTop+12),'finale sparks stay visible while ordinary entering/departing barge sparks keep the existing bounded canvas-clipping margin');
   assert.deepEqual(geometry.fireworks(age,.4,festival,event),dots,'repaint does not resample particles or launch timing');
  }
  assert.equal(geometry.fireworks(duration,.4,festival,event).length,0);
 }
 const renderer=fs.readFileSync(path.join(__dirname,'landscape.js'),'utf8');assert.match(renderer,/if\(reduced\|\|document\.hidden\)\{frame=0;return;\}/,'reduced or hidden scenes keep the existing stopped animation clock');assert.doesNotMatch(renderer.slice(renderer.indexOf('  function paintFireworks('),renderer.indexOf('  function paintClocktowerVisit(')),/setInterval|Date\.now|Math\.random|(?:lighter|screen)/,'fireworks retain deterministic pausable geometry and avoid flash compositing');
});

