 c.startsAt=null;const context={id:'inactive-overall-share',name:'Inactive',active:false};ctx.state.contexts.push(context);c.ctx=[context.id];assert.equal(ctx.chanceDisplayStats().get(c.id).probability,0);c.ctx=[];
