// #2254 (owner rule, 2026-11-06): "only 3 autosaves", which the owner
// clarified meant the daily backups. A successful save keeps this account's
// daily backups for today and the two calendar days before it, instead of
// seven; every other automatic copy keeps seven, and manual, promoted and
// pinned copies stay until they are deleted. Removing a daily backup's row
// never removes a board copy another backup or the board still uses: the head
// commit retires only snapshots nothing references.
test('RISK daily backup retention: a successful save keeps this account’s daily backups for three calendar days and other automatic copies for seven, and never trims manual, promoted or pinned copies or a board copy another backup still uses',async()=>{
 const {indexedDB}=await import('fake-indexeddb'),dbName='chain-scanner-daily-retention-'+Date.now()+'-'+Math.random();
 const raw=JSON.stringify(syncState({tasks:[syncTask('daily-retention','Daily retention board')]}));
 const storage=sharedScannerStorage({[LOCAL_HEAD_KEY]:raw,[SYNC_STORE_KEY]:raw}),at=day=>+new Date(2026,9,day,12);
 const {ctx,shim}=await loadApp({sharedStorage:storage,indexedDBProvider:indexedDB,deviceDbName:dbName,beforeStateReady:ctx=>setFakeTime(ctx,at(1))});
 const store=shim.window.ScannerDeviceStore;
 try{
  assert.equal(ctx.deviceStorageActive(),true,'fixture: the device store holds the board');
  const dailyOf=async day=>(await store.listBackups()).find(row=>row.kind==='daily'&&row.day===ctx.backupDay(at(day)));
  const kept={};
  for(let day=1;day<=8;day++){
   setFakeTime(ctx,at(day));ctx.addTask('Day '+day);assert.equal(await ctx.persist(),true,'day '+day+' saves');
   if(day===1){
    // A manual backup and an automatic cloud-adoption copy of the same board
    // share the daily backup's board copy.
    kept.daily1=await dailyOf(1);
    kept.manual=await ctx.saveDurableBackup('manual',kept.daily1.payload);
    kept.adoption1=await ctx.saveDurableBackup('before-cloud-adoption',kept.daily1.payload);
   }
   if(day===2){
    // The app's existing promotion keeps an automatic copy as a displaced-edit copy.
    kept.promoted=await dailyOf(2);
    assert.equal(await ctx.reclassifyDurableCloudRecoveryBackup(kept.promoted.id,kept.promoted.payload,'before-cloud-local-edit'),true,'fixture: the daily backup is promoted');
    kept.adoption2=await ctx.saveDurableBackup('before-cloud-adoption',kept.promoted.payload);
   }
   if(day===3){
    // The board pins this daily backup, as a cloud adoption pins its safety copy.
    kept.pinned=await dailyOf(3);ctx.state.protectedBackupIds=[kept.pinned.id];
   }
  }
  for(const name of ['daily1','manual','adoption1','promoted','adoption2','pinned'])assert.ok(kept[name]?.id,'fixture: '+name+' was saved');
  assert.equal(kept.manual.payload,kept.daily1.payload,'fixture: the manual backup and the first daily backup share one board copy');
  const rows=await store.listBackups(),ids=rows.map(row=>row.id);
  const dailyDays=[...rows.filter(row=>row.kind==='daily'&&row.id!==kept.pinned.id).map(row=>row.day)].sort();
  // Behaviour under test: this account's daily backups cover today and the two days before it.
  assert.deepEqual(dailyDays,[6,7,8].map(day=>ctx.backupDay(at(day))),'daily backups cover three calendar days');
  // Other automatic copies keep seven calendar days.
  assert.equal(ids.includes(kept.adoption1.id),false,'positive control: an automatic copy from eight days ago is retired');
  assert.equal(ids.includes(kept.adoption2.id),true,'an automatic copy from seven calendar days ago stays');
  // Manual, promoted and pinned copies stay, and so does the board copy they share.
  assert.equal(rows.find(row=>row.id===kept.manual.id)?.payload,kept.daily1.payload,'the manual backup stays restorable after the daily backup that shared its copy is trimmed');
  assert.equal(ids.includes(kept.daily1.id),false,'positive control: the first daily backup is trimmed');
  assert.equal(rows.find(row=>row.id===kept.promoted.id)?.kind,'before-cloud-local-edit','the promoted copy stays');
  assert.equal(ids.includes(kept.pinned.id),true,'the pinned daily backup stays while the board pins it');
  assert.deepEqual([...rows.filter(row=>row.kind==='latest').map(row=>row.day)],[ctx.backupDay(at(8))],'one latest copy, today');
  assert.equal((await store.readHead()).payload,JSON.stringify(ctx.state),'the board itself is the saved head');
 }finally{await store.close();}
});

// #2254 (owner rule): trimming stays with the account whose board a daily
// backup copies, and never reads a board copy to find out. A daily backup
// names that account when it is saved; one that names another account, or
// was saved before daily backups named one, keeps the seven-day rule, on the
// device and in the older backup list alike.
test('RISK daily backup retention scope: a save trims only this account’s daily backups to three calendar days, on this device and in the older backup list, while another account’s daily backups and those saved before daily backups named an account keep seven',async()=>{
 const dailyBoard2335=(raw,n)=>JSON.stringify({...JSON.parse(raw),futureData:{keep:'exact board facts '+n}});
 const f=await privateLegacyExpiryFixture({makeRows:(row,raw)=>[
  // #2335: distinct boards, so no daily backup is a redundant repeat of another one kept longer.
  row('private-own-trimmed','daily','2026-10-04',{account:null,payload:dailyBoard2335(raw,1)}),row('private-own-kept','daily','2026-10-05',{account:null,payload:dailyBoard2335(raw,2)}),
  row('private-other-account','daily','2026-10-04',{account:'another-account@example.test',payload:dailyBoard2335(raw,3)}),row('private-unnamed','daily','2026-10-04',{payload:dailyBoard2335(raw,4)}),
  row('private-expired','daily',PRIVATE_EXPIRY_OLD)]});try{
  assert.equal(f.ctx.state.syncAccount??null,null,'fixture: the board is signed out, so its daily backups name no account');
  assert.equal(await privateExpirySave(f),true);
  const legacy=privateExpiryLegacyRows(f).map(row=>row.id),durable=(await f.store.listBackups()).map(row=>row.id);
  for(const [where,ids] of [['the older backup list',legacy],['this device',durable]]){
   // Behaviour under test: this account's daily backup from three days before yesterday is trimmed.
   assert.equal(ids.includes('private-own-trimmed'),false,where+': this account’s daily backup outside three calendar days is trimmed');
   for(const id of ['private-own-kept','private-other-account','private-unnamed'])assert.equal(ids.includes(id),true,where+': '+id+' stays');
   assert.equal(ids.includes('private-expired'),false,where+': positive control: the seven-day rule still retires older copies');
  }
  await privateExpiryAssertCurrentBoard(f);
 }finally{await f.store.close();}
});

// #2264 (A): when a device with no unsynced edits takes a newer cloud board,
// for example one another device adopted over an unreadable generation, it
// keeps its earlier board as an automatic copy for seven calendar days, as
// Settings and the November 6 changelog promise. In browser storage, opening
// had already saved that same board as today's daily backup, and the copy
// made before taking the cloud board used to reuse it. Daily backups keep
// three days, so the earlier board disappeared four days early.
test('RISK daily backup retention adoption copy: in browser storage, the board a device had before taking another device’s newer cloud board stays restorable for seven calendar days, even when that day’s daily backup already holds the same board',async t=>{
 const at=day=>+new Date(2026,10,day,12),storage=sharedScannerStorage({}),apps=[],backends=[];
 t.after(async()=>{for(const backend of backends)backend.CS.suspend();for(const app of apps)await closeLegacyApp173(app);});
 // A browser-storage device (no device store) signed in to one shared cloud.
 const open=async(day,docs=null)=>{
  const app=await loadAppAtTime(at(day),{sharedStorage:storage});apps.push(app);
  assert.equal(app.ctx.deviceStorageActive(),false,'fixture: the board lives in browser storage');
  // The page still loads the shipped storage codec the cloud uses, as when the device store fails to open.
  vm.runInContext(fs.readFileSync(path.join(__dirname,'device-store-v2.js'),'utf8'),app.ctx,{filename:'device-store-v2.js'});app.ctx.window.ChainStorageV2=app.ctx.ChainStorageV2;
  const backend=await loadCloudBackendV2({runtimeWindow:app.ctx.window,sharedDocs:docs,failures:{authPending:true},timeoutMs:5000});backends.push(backend);
  backend.emitAuth({uid:'owner',email:'e@example.com'});app.ctx.closeModal();
  return {app,backend};
 };
 // Day 1: the account’s first board is in the cloud; this device reads it,
 // adds a task and the cloud acknowledges that board.
 const seed=await loadCloudBackendV2({timeoutMs:5000});backends.push(seed);
 const seedBoard=JSON.stringify(syncState({tasks:[syncTask('shared','Shared task')],syncAccount:'e@example.com',syncIdentity:'owner'}));
 assert.equal((await seed.CS.push(seedBoard,at(1),0)).ok,true,'fixture: the account’s first board is in the cloud');
 const first=await open(1,seed.docs);
 await first.app.ctx.cloudPull();await settleRecoveryOperations188(first.app.ctx);
 first.app.ctx.addTask('Task from this device');assert.equal(await first.app.ctx.persist(),true);
 vm.runInContext('clearTimeout(cloudTimer);cloudTimer=null',first.app.ctx);await first.app.ctx.sendPush();await settleRecoveryOperations188(first.app.ctx);
 assert.equal(first.app.ctx.state.syncDirty,false,'fixture: the cloud acknowledged this device’s board');
 assert.ok(first.app.ctx.state.tasks.some(task=>task.title==='Task from this device'),'fixture: this device’s board has its own task');
 const acknowledged=first.backend.docs.get('users/owner').rev;
 await closeLegacyApp173(first.app);first.backend.CS.suspend();
 // Another device publishes the next generation, without this device’s task.
 const other=await loadCloudBackendV2({sharedDocs:seed.docs,timeoutMs:5000});backends.push(other);
 const otherBoard=JSON.stringify(syncState({tasks:[syncTask('other-device','Board from the other device')],syncAccount:'e@example.com',syncIdentity:'owner'}));
 assert.equal((await other.CS.push(otherBoard,at(2),acknowledged)).ok,true,'fixture: the other device publishes the next revision');
 // Day 6: this device opens unchanged (opening saves today’s daily backup) and takes the newer cloud board.
 const later=await open(6,seed.docs),{ctx}=later.app;
 await flush();
 const prior=JSON.stringify(ctx.state);
 assert.equal(ctx.state.syncDirty,false,'fixture: this device has no unsynced edits');
 assert.ok(ctx.readLocalBackups().some(row=>row.kind==='daily'&&row.day===ctx.backupDay(at(6))&&row.payload===prior),'fixture: opening saved today’s daily backup of the same board');
 await ctx.cloudPull();await settleRecoveryOperations188(ctx);
 assert.ok(ctx.state.syncRev>acknowledged,'positive control: this device took the newer cloud board');
 assert.ok(ctx.state.tasks.some(task=>task.title==='Board from the other device'),'positive control: the other device’s board is on this device');
 const restorable=()=>ctx.readLocalBackups().some(row=>row.payload===prior);
 assert.equal(restorable(),true,'the earlier board is restorable right after taking the cloud board');
 // Behaviour under test: ordinary saves on each later day keep the earlier board restorable for seven calendar days.
 for(let day=7;day<=12;day++){
  setFakeTime(ctx,at(day));ctx.addTask('Day '+day);assert.equal(await ctx.persist(),true,'day '+day+' saves');
  assert.equal(restorable(),true,'the earlier board is still restorable on the '+(day-5)+(day===7?'nd':day===8?'rd':'th')+' calendar day');
 }
 setFakeTime(ctx,at(13));ctx.addTask('Day 13');assert.equal(await ctx.persist(),true);
 assert.equal(restorable(),false,'positive control: after seven calendar days the automatic copy retires');
});

// #2268 review: the #2264 (A) scenario with a chosen board. A browser-storage
// device acknowledges the account's board on day 1, another device publishes
// the next revision, and on day 6 this device opens unchanged (opening saves
// today's daily backup of that board), runs beforePull, then takes the newer
// cloud board. Answers the device's app, its board from before taking the
// cloud board, and whether that board is still restorable.
async function browserAdoptionDevice2268(t,{tasks,beforePull=async()=>{}}){
 const at=day=>+new Date(2026,10,day,12),storage=sharedScannerStorage({}),apps=[],backends=[];
 t.after(async()=>{for(const backend of backends)backend.CS.suspend();for(const app of apps)await closeLegacyApp173(app);});
 const open=async(day,docs)=>{
  const app=await loadAppAtTime(at(day),{sharedStorage:storage});apps.push(app);
  assert.equal(app.ctx.deviceStorageActive(),false,'fixture: the board lives in browser storage');
  vm.runInContext(fs.readFileSync(path.join(__dirname,'device-store-v2.js'),'utf8'),app.ctx,{filename:'device-store-v2.js'});app.ctx.window.ChainStorageV2=app.ctx.ChainStorageV2;
  const backend=await loadCloudBackendV2({runtimeWindow:app.ctx.window,sharedDocs:docs,failures:{authPending:true},timeoutMs:5000});backends.push(backend);
  backend.emitAuth({uid:'owner',email:'e@example.com'});app.ctx.closeModal();
  return {app,backend};
 };
 const seed=await loadCloudBackendV2({timeoutMs:5000});backends.push(seed);
 assert.equal((await seed.CS.push(JSON.stringify(syncState({tasks,syncAccount:'e@example.com',syncIdentity:'owner'})),at(1),0)).ok,true,'fixture: the account’s first board is in the cloud');
 const first=await open(1,seed.docs);
 await first.app.ctx.cloudPull();await settleRecoveryOperations188(first.app.ctx);
 first.app.ctx.addTask('Task from this device');assert.equal(await first.app.ctx.persist(),true);
 vm.runInContext('clearTimeout(cloudTimer);cloudTimer=null',first.app.ctx);await first.app.ctx.sendPush();await settleRecoveryOperations188(first.app.ctx);
 assert.equal(first.app.ctx.state.syncDirty,false,'fixture: the cloud acknowledged this device’s board');
 const acknowledged=first.backend.docs.get('users/owner').rev;
 await closeLegacyApp173(first.app);first.backend.CS.suspend();
 const other=await loadCloudBackendV2({sharedDocs:seed.docs,timeoutMs:5000});backends.push(other);
 const otherBoard=JSON.stringify(syncState({tasks:[...tasks,syncTask('other-device','Board from the other device')],syncAccount:'e@example.com',syncIdentity:'owner'}));
 assert.equal((await other.CS.push(otherBoard,at(2),acknowledged)).ok,true,'fixture: the other device publishes the next revision');
 const {ctx}=(await open(6,seed.docs)).app;
 await flush();
 await beforePull(ctx);
 const prior=JSON.stringify(ctx.state);
 assert.equal(ctx.state.syncDirty,false,'fixture: this device has no unsynced edits');
 assert.ok(ctx.readLocalBackups().some(row=>row.kind==='daily'&&row.day===ctx.backupDay(at(6))&&row.payload===prior),'fixture: opening saved today’s daily backup of the same board');
 await ctx.cloudPull();await settleRecoveryOperations188(ctx);
 assert.ok(ctx.state.tasks.some(task=>task.title==='Board from the other device'),'positive control: this device took the newer cloud board');
 return {ctx,at,prior,restorable:()=>ctx.readLocalBackups().some(row=>row.payload===prior)};
}

// #2268 review (finding 2): #2264 (A) stopped today's daily backup standing in
// for the copy kept before taking a newer cloud board, so browser storage wrote
// a second full copy of the same board. Automatic copies share a budget of
// 1,000,000 units, so with a board of about 400,000 characters that duplicate
// pushed the earlier board out on the very day the cloud board was taken.
test('RISK daily backup retention adoption copy: in browser storage, a large board a device had before taking another device’s newer cloud board stays restorable on that day',async t=>{
 const tasks=Array.from({length:340},(_,i)=>syncTask('pad-'+i,'Padded task '+i+' '+'w'.repeat(200)));
 const {ctx,at,prior,restorable}=await browserAdoptionDevice2268(t,{tasks});
 assert.ok(prior.length>=380000&&prior.length<=430000,'fixture: the board is about 400,000 characters ('+prior.length+')');
 // Behaviour under test: the earlier board stays restorable through the adoption day's saves.
 assert.equal(restorable(),true,'the earlier board is restorable right after taking the cloud board');
 ctx.addTask('Later on the same day');assert.equal(await ctx.persist(),true,'a save on the same day');
 assert.equal(restorable(),true,'the earlier board is still restorable after a save on the same day');
});

// #2268 review (finding 10): a manual backup of the same board stood in for
// the copy kept before taking a newer cloud board. The Settings reminder asks
// people to delete manual backups they no longer need; deleting that one left
// only the three-day daily backup, so the earlier board disappeared on the
// fourth day instead of the seventh.
test('RISK daily backup retention adoption copy: a manual backup of the same board does not stand in for the copy kept before taking a newer cloud board, so deleting it keeps the earlier board restorable for seven calendar days',async t=>{
 const {ctx,at,prior,restorable}=await browserAdoptionDevice2268(t,{tasks:[syncTask('shared','Shared task')],beforePull:async ctx=>{
  await ctx.onAction('make-manual-backup',{});await flush();await flush();ctx.closeModal();
 }});
 assert.ok(ctx.readLocalBackups().some(row=>row.kind==='manual'&&row.payload===prior),'fixture: a manual backup holds the earlier board');
 for(let day=7;day<=12;day++){
  setFakeTime(ctx,at(day));
  if(day===7){
   const manual=ctx.readLocalBackups().find(row=>row.kind==='manual'&&row.payload===prior);
   vm.runInContext('confirm=()=>true',ctx);ctx.openSettings();
   await ctx.onAction('delete-local-backup',{dataset:{id:manual.id}});await flush();ctx.closeModal();
   assert.equal(ctx.readLocalBackups().some(row=>row.kind==='manual'&&row.payload===prior),false,'fixture: the person deleted the manual backup');
  }
  ctx.addTask('Day '+day);assert.equal(await ctx.persist(),true,'day '+day+' saves');
  // Behaviour under test: the copy kept before taking the cloud board outlives the deleted manual backup.
  assert.equal(restorable(),true,'the earlier board is still restorable on the '+(day-5)+(day===7?'nd':day===8?'rd':'th')+' calendar day');
 }
});

// #2254 (owner rule): Settings, Help and the November 6 changelog say what
// the rule keeps. Every Help answer keeps the 130-word limit.
// #2303: what left Settings is in the Data and backups FAQ, and the current
// changelog describes the simpler Settings.
test('RISK simpler Settings guidance: the Data and backups FAQ holds the moved sync, retention and error explanations within 130 words, and the current changelog describes the simpler Settings',async t=>{
 const app=await loadApp();t.after(()=>app.dispose());
 for(const id of ['appChangelogCurrent','appChangelog'])app.shim.document.getElementById(id).innerHTML=html.match(new RegExp('<template id="'+id+'">([\\s\\S]*?)<\\/template>'))[1];
 await app.ctx.onAction('help',{});const markup=app.shim.document.getElementById('modalRoot').innerHTML;
 const data=markup.split('<summary><h3>Data and backups</h3></summary>')[1]?.split('</details>')[0]||'';
 const answer=question=>data.split('<dt>'+question+'</dt><dd>')[1]?.split('</dd>')[0]||'';
 assert.match(answer('When does cloud sync check for changes?'),/Cloud sync refreshes on load, when you return, and when another device saves\. Independent decisions combine; conflicting current choices use when each choice was made\. Drafts and pressed controls wait until you finish\./);
 assert.match(answer('How long do backups stay on this device?'),/Daily copies stay on this device for today and the two calendar days before it/);
 assert.match(answer('When are old backups cleaned up?'),/Cleanup waits if the board or backup list changes or storage refuses the write\./);
 assert.match(answer('How do Settings save?'),/Every setting saves as soon as you change it[\s\S]*returns to the last valid value/);
 assert.match(answer('What can I do if a save or sync fails?'),/Recent sync errors, in the Debug log under Troubleshooting,/);
 const words=[...markup.matchAll(/<dt>([\s\S]*?)<\/dt><dd>([\s\S]*?)<\/dd>/g)].filter(m=>m[2].replace(/<[^>]+>/g,' ').split(/\s+/).filter(Boolean).length>130).map(m=>m[1]);
 assert.deepEqual(words,[],'every Help answer stays within the 130-word limit');
 assert.doesNotMatch(data,/Download recovery file|Save settings is at the bottom|Paste JSON/,'the FAQ names the controls Settings now shows');
 assert.doesNotMatch(markup.split('data-changelog-notes>')[0]+(markup.split('data-changelog-notes>')[1]||'').split('</details>').slice(1).join('</details>'),/Save settings applies|in Settings and Save settings/,'no FAQ answer sends anyone to the removed Save settings button');
 // #2334: a later dated entry now sits above it, so read the November 10 entry by its date.
 const current=(markup.split('data-changelog-notes>')[1]||'').split('<h3>November 10, 2026</h3>')[1]?.split('</ul>')[0]||'';
 assert.match(current,/<li>Settings is much shorter\./,'the newest changelog entry describes the simpler Settings');
 assert.match(current,/Every setting now saves as soon as you change it, and a number out of range returns to the last valid one\./);
 assert.match(current,/Download backup/);assert.match(current,/Download board only/);assert.match(current,/Troubleshooting/);
});

