test('RISK daily backup retention guidance: the Data and backups FAQ and the November 6 changelog say daily backups cover three calendar days and other automatic copies seven, that a cloud recovery keeps them until the cloud confirms the board, and that manual and kept copies stay until deleted',async t=>{
 const app=await loadApp();t.after(()=>app.dispose());
 for(const id of ['appChangelogCurrent','appChangelog'])app.shim.document.getElementById(id).innerHTML=html.match(new RegExp('<template id="'+id+'">([\\s\\S]*?)<\\/template>'))[1];
 app.ctx.openSettings();const settings=app.shim.document.getElementById('modalRoot').innerHTML;
 assert.doesNotMatch(settings,/Daily local backups|Daily copies stay on this device/,'#2303: Settings leaves retention details to the FAQ');
 await app.ctx.onAction('help',{});
 const section=app.shim.document.getElementById('modalRoot').innerHTML.split('<summary><h3>Data and backups</h3></summary>')[1]?.split('<dt>How long do backups stay on this device?</dt><dd>')[1]?.split('</dd>')[0]||'';
 assert.match(section,/Daily copies stay on this device for today and the two calendar days before it, so at most three; other automatic copies stay for up to seven calendar days/);
 assert.match(section,/While cloud recovery waits or holds your board, before the cloud confirms it, daily copies keep the seven days\./);
 assert.match(section,/Daily copies saved before this update, or holding another account’s board, also keep seven days\./);
 assert.match(section,/Manual, displaced local edits and unsynced account-switch copies stay until you delete them/);
 // #2333 review (#2335): a save now clears a draft or other-browser copy that repeats another copy, and a draft the board holds.
 assert.match(section,/Stale tab drafts and other-browser copies stay until you delete them too, unless a save clears a repeat of another copy or a draft the saved board holds\./);
 assert.doesNotMatch(section,/Automatic copies stay on this device for up to seven calendar days/);
 await app.ctx.onAction('help',{});const markup=app.shim.document.getElementById('modalRoot').innerHTML;
 const backups=markup.split('<dt>How do backups and Restore work?</dt><dd>')[1]?.split('</dd>')[0]||'';
 assert.match(backups,/Automatic backups cover today and the previous six local dates, daily backups only the previous two;/);
 assert.match(backups,/Manual and protected recovery copies remain until you delete them\./);
 const answers=[...markup.matchAll(/<dt>([\s\S]*?)<\/dt><dd>([\s\S]*?)<\/dd>/g)].map(match=>({question:match[1],text:match[2].replace(/<[^>]+>/g,' ')}));
 assert.deepEqual(answers.filter(row=>row.text.split(/\s+/).filter(Boolean).length>130).map(row=>row.question),[],'every Help answer stays within the 130-word limit');
 const release=(markup.split('data-changelog-notes>')[1]||'').split('<h3>November 6, 2026</h3>')[1]?.split('</ul>')[0]||'';
 assert.match(release,/<li>Daily backups now cover today and the two calendar days before it, so at most three stay on this device instead of seven days of them\./);
 assert.match(release,/Other automatic copies still stay up to seven days, and manual backups and every copy the app keeps until you delete it/);
 assert.match(release,/While cloud recovery waits or holds your board, daily backups keep seven days until the cloud confirms it\./);
 for(const text of [section,backups,release.replace(/<[^>]+>/g,' ')])assert.doesNotMatch(text,/desktop|computer|laptop|\bMac\b/i);
});


test('RISK Squared Weighting: exact percentage math full precision and frozen quadratic ordering',async()=>{
 const {ctx}=await loadApp({seed:941});
 assert.equal(ctx.squaredPercentageWeight(.5),25);
 assert.equal(ctx.squaredPercentageWeight(1),100);
 assert.equal(ctx.squaredPercentageWeight(2)/ctx.squaredPercentageWeight(1),4);
 for(const invalid of [0,-1,NaN,Infinity])assert.equal(ctx.squaredPercentageWeight(invalid),0);
 const tasks=[ctx.addTask('A'),ctx.addTask('B'),ctx.addTask('C')];
 const weights=new Map(tasks.map((t,i)=>[t.id,[.1,.2,.7][i]]));ctx.chanceWeight=t=>weights.get(t.id);
 ctx.state.scanMode='squared';ctx.resetChance();const seed=ctx.state.chance.seed;
 const stats=ctx.chanceDisplayStats();
 for(let i=0;i<tasks.length;i++)assert.ok(Math.abs(stats.get(tasks[i].id).probability-[1/54,4/54,49/54][i])<1e-12);
 const order=Array.from(ctx.candidateOrder(tasks),t=>t.id);
 for(const task of tasks){const u=(ctx.chanceHash(seed+':'+task.id)+.5)/4294967296;assert.ok(Math.abs(ctx.squaredScore(task)-(-Math.log(u)/((weights.get(task.id)/.7)**2)))<1e-12);}
 weights.set(tasks[0].id,.99);assert.deepEqual(Array.from(ctx.candidateOrder(tasks),t=>t.id),order,'live ratings never reroll this pass');
 assert.equal(ctx.state.chance.seed,seed);
 assert.deepEqual(Array.from(ctx.candidateOrder([])),[]);
 ctx.state.chance.weights=Object.fromEntries(tasks.map(t=>[t.id,0]));assert.deepEqual(Array.from(ctx.candidateOrder(tasks),t=>t.id),tasks.map(t=>t.id).sort());
});

