test('RISK Last task WOOP browser: mounted controls responsive saved revisit delete and offline reload',
 {skip:!process.env.WOOP_BROWSER_URL},async()=>{
 const {chromium,webkit}=await import(process.env.PLAYWRIGHT_MODULE||'playwright'),origin=new URL(process.env.WOOP_BROWSER_URL).origin;
 const output=process.env.WOOP_SCREENSHOT_DIR;if(output)fs.mkdirSync(output,{recursive:true});const samples=[];
 for(const [engine,type,sizes]of [['chrome',chromium,[[390,844],[768,1024],[1366,768],[568,320]]],['webkit',webkit,[[390,844],[768,1024]]]]){
  const browser=await type.launch({headless:true,...(engine==='chrome'?{channel:'chrome'}:{})});
  try{
   for(const [width,height]of sizes){
    const context=await browser.newContext({viewport:{width,height},reducedMotion:'reduce'}),errors=[];
    await context.addInitScript(()=>{Object.defineProperty(window,'FIREBASE_CONFIG',{value:Object.freeze({}),writable:false,configurable:false});localStorage.setItem('fvp:chain-scanner:landscape-motion','reduced');});
    await context.route('**/*',route=>new URL(route.request().url()).origin===origin?route.continue():route.abort());
    const page=await context.newPage();page.on('pageerror',error=>errors.push(error.message));await page.goto(process.env.WOOP_BROWSER_URL);await page.waitForFunction(()=>typeof state!=='undefined'&&state?.tasks);
    const id=await page.evaluate(()=>{closeModal();document.querySelectorAll('dialog[open]').forEach(d=>d.close());state.addOpen=true;const task=addTask('Synthetic final task with a long title for responsive wrapping');state.chain=[task.id];state.mode='work';render();return task.id;});
    assert.equal(await page.locator('[data-act=woop-start]').count(),0,'off by default');
    const setting=async enabled=>{await page.evaluate(()=>openSettings());await page.locator('summary').filter({hasText:'Scanning and recurrence'}).click();await page.locator('#stLastTaskWoop').setChecked(enabled);await page.locator('[data-act=close-modal]').click();};
    await setting(true);
    for(let count=0;count<3;count++){
     assert.equal(await page.locator('[data-act=woop-start]').count(),count===2?1:0,'recorded dislodge boundary '+count);
     if(count<2){await page.locator('[data-act=dislodge]').click();await page.evaluate(id=>dotTask(id),id);}
    }
    await page.locator('[data-act=woop-start]').click();await page.locator('#woopAnswer').fill('Cancelled private draft');await page.locator('[data-act=woop-next]').click();await page.getByRole('button',{name:'Cancel',exact:true}).click();assert.equal(await page.evaluate(id=>taskById(id).woopPlan,id),undefined);
    await page.locator('[data-act=woop-start]').click();
    for(const [step,answer]of ['Best outcome: take a useful first step.','Obstacle: uncertainty about where to begin.','If I feel uncertain, then I will write one concrete next action.'].entries()){
     await page.locator('#woopAnswer').fill(answer);
     if(step===2&&output)await page.screenshot({path:path.join(output,engine+'-'+width+'-walkthrough.png'),fullPage:true});
     await page.locator('[data-act=woop-next]').click();
    }
    assert.equal(await page.locator('[data-act=woop-start]').count(),0);assert.equal(await page.locator('[data-act=woop-delete]').count(),1);
    await page.evaluate(()=>persist());
    for(const theme of ['light','dark']){
     await page.evaluate(theme=>setTheme(theme),theme);
     const sample=await page.evaluate(()=>{
      const inspect=selector=>{const e=document.querySelector(selector),s=getComputedStyle(e),r=e.getBoundingClientRect();return {fontFamily:s.fontFamily,fontSize:s.fontSize,fontWeight:s.fontWeight,lineHeight:s.lineHeight,color:s.color,backgroundColor:s.backgroundColor,left:r.left,right:r.right,width:r.width};};
      return {plan:inspect('.woop-saved dd'),delete:inspect('[data-act=woop-delete]'),viewport:innerWidth,pageWidth:document.documentElement.scrollWidth,theme:document.documentElement.dataset.theme};
     });
     assert.equal(sample.theme,theme);assert.ok(sample.pageWidth<=width+1,'no page overflow');assert.ok(sample.delete.left>=0&&sample.delete.right<=width+1,'Delete fits');assert.equal(sample.delete.backgroundColor,'rgb(255, 255, 255)','Delete stays white in supported themes');
     if(engine==='chrome'){
      const cdp=await context.newCDPSession(page);await cdp.send('DOM.enable');await cdp.send('CSS.enable');const {root}=await cdp.send('DOM.getDocument');const {nodeId}=await cdp.send('DOM.querySelector',{nodeId:root.nodeId,selector:'.woop-saved dd'});sample.resolvedFonts=(await cdp.send('CSS.getPlatformFontsForNode',{nodeId})).fonts.map(font=>font.familyName);assert.ok(sample.resolvedFonts.length);await cdp.detach();
     }
     samples.push({engine,width,height,theme,...sample});if(output)await page.screenshot({path:path.join(output,engine+'-'+width+'-'+theme+'-saved.png'),fullPage:true});
    }
    await setting(false);assert.equal(await page.locator('.woop-saved').count(),0);assert.ok(await page.evaluate(id=>taskById(id).woopPlan,id));await setting(true);assert.equal(await page.locator('.woop-saved').count(),1);
    await page.reload();await page.waitForFunction(id=>typeof state!=='undefined'&&state?.tasks&&taskById(id)?.woopPlan,id);await page.evaluate(id=>{state.mode='work';state.chain=[id];render();},id);assert.equal(await page.locator('.woop-saved').count(),1);
    // Actual mounted order in both task forms, with the search node retained.
    for(const scope of ['add','edit']){
     if(scope==='edit')await page.evaluate(id=>openEdit(id),id);else await page.evaluate(()=>{closeModal();state.addOpen=true;render();});
     const search=page.locator('#'+scope+'DependencySearch');await search.fill('Synthetic');await search.focus();
     const geometry=await page.evaluate(scope=>{const filter=document.getElementById(scope+'DependencySearch'),choices=filter.parentElement.parentElement.querySelector('.dependency-choices'),ever=document.getElementById(scope==='add'?'addEver':'etEver');return {choices:choices.getBoundingClientRect().bottom,filter:filter.getBoundingClientRect().top,filterBottom:filter.getBoundingClientRect().bottom,ever:ever.getBoundingClientRect().top,focused:document.activeElement===filter};},scope);
     assert.ok(geometry.choices<=geometry.filter+1);assert.ok(geometry.filterBottom<=geometry.ever+1);assert.equal(geometry.focused,true);assert.equal(await page.locator('label[for='+scope+'DependencySearch]').textContent(),'Filter dependencies');
     if(output)await page.screenshot({path:path.join(output,engine+'-'+width+'-'+scope+'-dependencies.png'),fullPage:true});
    }
    await page.evaluate(()=>closeModal());await page.locator('[data-act=woop-delete]').click();await page.evaluate(()=>persist());assert.equal(await page.locator('[data-act=woop-start]').count(),1);
    if(engine==='chrome'&&width===390){await page.evaluate(()=>navigator.serviceWorker.ready);await page.reload();await page.waitForFunction(()=>!!navigator.serviceWorker.controller);await context.setOffline(true);await page.reload();await page.waitForFunction(id=>typeof state!=='undefined'&&state?.tasks&&taskById(id),id);assert.equal(await page.evaluate(id=>taskById(id).woopPlan,id),null,'offline reload preserves deletion');await context.setOffline(false);}
    assert.deepEqual(errors,[]);await context.close();
   }
  }finally{await browser.close();}
 }
 if(output)fs.writeFileSync(path.join(output,'typography-samples.json'),JSON.stringify({candidate:spawnSync('git',['rev-parse','HEAD'],{cwd:__dirname,encoding:'utf8'}).stdout.trim(),samples},null,2));
});

test('RISK per-edge dependency controls: Add and Edit binary checkbox transitions persist hard and soft without losing search selections',async()=>{
 const {ctx,shim}=await loadApp();const root=ctx.addTask('Recurring root'),owner=ctx.addTask('Owner');root.evergreen=true;
 ctx.setTaskPrerequisites(owner.id,[root.id]);
 ctx.openEdit(owner.id);
 assert.match(shim.document.getElementById('modalRoot').innerHTML,/Hard dependency/,'selected links require the requested checkbox');
 assert.equal(ctx.taskDependencyMode(owner,root.id),'soft');
 const checkbox=shim.document.getElementById('editDependencyHard0');Object.assign(checkbox,{id:'editDependencyHard0',dataset:{dependencyHard:'edit',dependencyId:root.id},matches:()=>false,checked:true});
 shim.document.dispatchEvent({type:'change',target:checkbox});ctx.onAction('save-edit',{dataset:{id:owner.id}});
 assert.equal(ctx.taskDependencyMode(owner,root.id),'hard');ctx.completeTask(root);assert.equal(ctx.isEligible(owner),false,'evergreen Done never clears hard');
 ctx.openEdit(owner.id);checkbox.checked=false;shim.document.dispatchEvent({type:'change',target:checkbox});ctx.onAction('save-edit',{dataset:{id:owner.id}});
 assert.equal(ctx.taskDependencyMode(owner,root.id),'soft');assert.equal(ctx.isEligible(owner),true,'rest clears soft');ctx.reopenTask(root);assert.equal(ctx.isEligible(owner),false,'recurrence blocks again');
 ctx.renderAddPanel();const select=shim.document.getElementById('addPrerequisite');Object.assign(select,{dataset:{dependencyScope:'add'},matches:()=>false,value:root.id});shim.document.dispatchEvent({type:'change',target:select});
 assert.equal(ctx.quickAddTaskOptions().dependencyModes[root.id],'soft');
 const addBox=shim.document.getElementById('addDependencyHard0');Object.assign(addBox,{dataset:{dependencyHard:'add',dependencyId:root.id},matches:()=>false,checked:true});shim.document.dispatchEvent({type:'change',target:addBox});
 const added=ctx.addTask('New owner',false,[],{},ctx.quickAddTaskOptions());assert.equal(ctx.taskDependencyMode(added,root.id),'hard');
 await ctx.persist();const reload=await loadApp({seedStorage:{[SYNC_STORE_KEY]:shim.localStorage.getItem(SYNC_STORE_KEY)}});assert.equal(reload.ctx.taskDependencyMode(reload.ctx.state.tasks.find(t=>t.id===owner.id),root.id),'soft');
});

test('RISK per-edge dependency semantics: mixed edges intrinsic eligibility deletion Undo and cyclic chains remain bounded',async()=>{
 const {ctx}=await loadApp();const a=ctx.addTask('A'),b=ctx.addTask('B'),c=ctx.addTask('C');ctx.setTaskPrerequisites(c.id,[a.id,b.id]);ctx.writeTaskDependencyModes(c,{[a.id]:'hard',[b.id]:'soft'});
 b.startsAt='2999-01-01';assert.equal(ctx.isEligible(c),false);ctx.completeTask(a);assert.equal(ctx.isEligible(c),true);b.startsAt=null;assert.equal(ctx.isEligible(c),false);
 ctx.deleteTask(b.id);assert.equal(ctx.isEligible(c),true);ctx.undo();assert.equal(ctx.isEligible(ctx.state.tasks.find(t=>t.id===c.id)),false);
 ctx.setTaskPrerequisites(a.id,[c.id]);ctx.reopenTask(ctx.state.tasks.find(t=>t.id===a.id));ctx.writeTaskDependencyModes(ctx.state.tasks.find(t=>t.id===a.id),{[c.id]:'soft'});assert.equal(ctx.isEligible(ctx.state.tasks.find(t=>t.id===a.id)),false);assert.equal(ctx.isEligible(ctx.state.tasks.find(t=>t.id===c.id)),false,'cycles use intrinsic target eligibility and never recurse');
 const stale=JSON.parse(JSON.stringify(ctx.state.tasks.find(t=>t.id===c.id)));ctx.writeTaskDependencyModes(ctx.state.tasks.find(t=>t.id===c.id),{[a.id]:'soft'});ctx.mergeTaskPrerequisites(ctx.state.tasks.find(t=>t.id===c.id),stale);assert.equal(ctx.taskDependencyMode(ctx.state.tasks.find(t=>t.id===c.id),a.id),'soft','stale mode cannot replace explicit change');
});

test('RISK per-edge dependency sync: explicit modes survive stale clients while Undo Restore and readd express fresh intent',async()=>{
 const {ctx}=await loadApp();const root=ctx.addTask('Root'),owner=ctx.addTask('Owner');ctx.setTaskPrerequisites(owner.id,[root.id]);
 const legacy=JSON.parse(JSON.stringify(owner));ctx.writeTaskDependencyModes(owner,{[root.id]:'hard'});const hard=JSON.parse(JSON.stringify(owner));ctx.pushUndo();ctx.writeTaskDependencyModes(owner,{[root.id]:'soft'});
 const soft=JSON.parse(JSON.stringify(owner));ctx.mergeTaskPrerequisites(owner,hard);assert.equal(ctx.taskDependencyMode(owner,root.id),'soft');
 const reverse=JSON.parse(JSON.stringify(hard));ctx.mergeTaskPrerequisites(reverse,soft);assert.equal(ctx.taskDependencyMode(reverse,root.id),'soft');
 ctx.mergeTaskPrerequisites(owner,legacy);assert.equal(ctx.taskDependencyMode(owner,root.id),'soft');
 ctx.undo();const restored=ctx.state.tasks.find(t=>t.id===owner.id);assert.equal(ctx.taskDependencyMode(restored,root.id),'hard');ctx.mergeTaskPrerequisites(restored,soft);assert.equal(ctx.taskDependencyMode(restored,root.id),'hard','stale soft does not undo Undo');
 ctx.replaceTaskPrerequisites(legacy,restored);assert.equal(ctx.taskDependencyMode(legacy,root.id),'soft','Restore of old links explicitly chooses the binary soft default with fresh causal evidence');ctx.mergeTaskPrerequisites(legacy,restored);assert.equal(ctx.taskDependencyMode(legacy,root.id),'soft');
 ctx.setTaskPrerequisites(restored.id,[]);ctx.openEdit(restored.id);
 ctx.writeTaskPrerequisites(restored,[root.id]);ctx.writeTaskDependencyModes(restored,{[root.id]:'soft'});ctx.mergeTaskPrerequisites(restored,hard);assert.equal(ctx.taskDependencyMode(restored,root.id),'soft');
 const board=JSON.parse(JSON.stringify(ctx.state)),before=JSON.stringify(board);ctx.hydrateState(board);assert.equal(JSON.stringify(board),before,'existing normalized boards do not acquire mode edits on load');
});

test('RISK per-edge dependency eligibility: search pass marks contexts dates and evergreen expiry use the same bounded rule',async()=>{
 const {ctx}=await loadApp();const target=ctx.addTask('Target'),owner=ctx.addTask('Owner');ctx.setTaskPrerequisites(owner.id,[target.id]);ctx.writeTaskDependencyModes(owner,{[target.id]:'soft'});
 ctx.state.considered[target.id]='cant';ctx.state.chain=[target.id];assert.equal(ctx.isEligible(owner),false,'pass marks and dot position do not make soft targets intrinsically ineligible');
 ctx.state.contexts=[{id:'context',name:'Context',active:false}];target.ctx=['context'];assert.equal(ctx.isEligible(owner),true);ctx.state.contexts[0].active=true;assert.equal(ctx.isEligible(owner),false);ctx.state.contexts[0].excluded=true;assert.equal(ctx.isEligible(owner),true);
 target.ctx=[];target.startsAt='2999-01-01';assert.equal(ctx.isEligible(owner),true);target.startsAt=null;target.evergreen=true;target.evergreenHours=18;target.evergreenResetAtDay=false;ctx.completeTask(target);assert.equal(ctx.isEligible(owner),true);
 target.lastDoneAt=Date.now()-19*3600000;assert.equal(ctx.isEligible(owner),false,'automatic recurrence blocks soft without removing edge');
 ctx.writeTaskDependencyModes(owner,{[target.id]:'hard'});target.done=true;assert.equal(ctx.isEligible(owner),false,'even imported Done evergreen blocks hard');target.evergreen=false;assert.equal(ctx.isEligible(owner),true);
});

