 assert.doesNotMatch(scanner(),/data-act="(?:bench-)?postpone"/);assert.equal(JSON.stringify(ctx.state.tasks),tasks);assert.equal(JSON.stringify(ctx.state.chain),chain);assert.equal(ctx.state.candidateId,b.id);
